public class UseFrostBlock : SkillState
{
	public new static string staticID = "UseFrostBlock";

	private static float blockDuration = 0.625f;

	private int blockStopwatchID;

	private FrostBlock currentFB;

	private IceTrap currentIT;

	public override string OnEnterAnimStr => parent.PBAoEAnimStr;

	public override string OnHoldAnimStr => parent.PBAoEAnimStr;

	public UseFrostBlock(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isMeleeSkill = true;
		isHoldSkill = true;
		SetAnimTimes(0f, 0f, 0.35f, 0.35f, 0.5f);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		parent.health.SetInvulnerabilityDuration(blockDuration + 0.1f);
		blockStopwatchID = ChaosStopwatch.Begin(blockDuration);
		parent.hud.castBar.StartCast(blockStopwatchID, givenStatus: false);
		parent.ToggleEnemyFloorCollisions(status: false);
		CreateFrostBlock();
		if (IsEmpowered)
		{
			CreateTrapRing(parent.transform.position);
		}
	}

	public override void HandleHoldButton()
	{
		parent.anim.PlayDirectional(OnHoldAnimStr, -1, animHoldTime);
		holdReleased = ChaosStopwatch.Check(blockStopwatchID);
	}

	public override void ExecuteSkill()
	{
		base.ExecuteSkill();
		parent.anim.PlayDirectional(parent.PBAoEAnimStr, -1, animExecTime);
		currentFB = null;
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.hud.castBar.EndCast();
		parent.ToggleEnemyFloorCollisions();
		if (currentFB != null)
		{
			currentFB.StopFollow();
		}
	}

	private void CreateFrostBlock()
	{
		currentFB = ChaosInst<FrostBlock>(FrostBlock.Prefab, parent.transform.position);
		currentFB.Init(parent.transform, blockDuration, parent.skillCategory, skillID, 1, (!IsEmpowered) ? 2.5f : 3f);
		CameraController.ShakeCamera(0.2f);
	}

	private void CreateTrapRing(Vector2 givenPosition)
	{
		for (int i = 1; i < 12; i += 2)
		{
			CreateIceTrap(givenPosition, Globals.GetCirclePositionVector(12, i) * 2f);
		}
	}

	private void CreateIceTrap(Vector2 givenStart, Vector2 givenOffset)
	{
		currentIT = ChaosInst<IceTrap>(IceTrap.Prefab, givenStart);
		currentIT.attack.SetAttackInfo(parent.skillCategory, skillID, 2);
		currentIT.armTime = 0.1f;
		currentIT.duration = 0.5f;
		currentIT.attackEnemies = true;
		currentIT.throwScript.throwHeight = 1f;
		currentIT.throwScript.moveSpeed = 24f;
		currentIT.throwScript.baseFlightTime = 0.125f;
		currentIT.throwScript.layerMask = ChaosCollisions.layerAll;
		currentIT.throwScript.ThrowToTargetVector(givenStart + givenOffset);
	}
}

public class UseFrostFan : ProjectileAttackState
{
	public new static string staticID = "UseFrostFan";

	private static int projectileCount = 5;

	private int shotCounter;

	private int shotStopwatchID;

	private bool shotStarted;

	private bool shotFinished;

	private List<Vector2> targetVecList = new List<Vector2>();

	private Vector2 perpendOffset;

	private Vector2 attackPosition;

	private static float moveSpeed = 12f;

	private FrostFanProjectile currentFP;

	private int ultCounter;

	private bool ultFinalShot;

	public override string OnEnterAnimStr => (!parent.isFacingRight) ? parent.ForehandAnimStr : parent.BackhandAnimStr;

	public UseFrostFan(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		hasSignatureVariant = true;
		SetAnimTimes(0.15f, 0.2f, 0.3f, 0.5f, 0.75f);
	}

	public override void OnEnter()
	{
		base.OnEnter();
		targetVecList.Clear();
		for (int num = 2; num >= -2; num--)
		{
			targetVecList.Add(Globals.GetRotatedCircleVector(24, num, inputVector));
		}
		shotStarted = false;
		shotFinished = false;
		shotCounter = 0;
		if (isUltimate)
		{
			ultCounter = 2;
			ultFinalShot = false;
			perpendOffset = Globals.GetPerpendicular(inputVector) * 0.5f;
			SetSkillLevel(3);
		}
		else
		{
			SetSkillLevel((!IsEmpowered) ? 1 : 2);
		}
		parent.movement.moveVector = -inputVector;
		parent.movement.MoveToMoveVector(moveSpeed);
	}

	public override void ExecuteSkill()
	{
		if (!shotStarted)
		{
			shotStarted = true;
			shotStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, 0.025f, projectileCount);
			parent.movement.EndMovement();
			SoundManager.PlayWithDistAndSPR("StandardThrow", parent.transform.position);
			SoundManager.PlayWithDistAndSPR("IceDash", parent.transform.position);
			CameraController.ShakeCamera(0.3f);
		}
		if (!shotFinished)
		{
			return;
		}
		if (isUltimate && ultCounter > 0)
		{
			ultCounter--;
			shotFinished = false;
			if (ultCounter == 0)
			{
				ultFinalShot = true;
				shotStopwatchID = ChaosStopwatch.Begin(0.15f);
				parent.anim.PlayDirectional(parent.PBAoEAnimStr);
			}
			else
			{
				shotStarted = false;
				shotCounter = 0;
				targetVecList.Reverse();
				parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animStartTime);
			}
			parent.movement.MoveToMoveVector(moveSpeed);
		}
		else
		{
			base.ExecuteSkill();
		}
	}

	public override void FixedUpdate()
	{
		if (!shotStarted || shotFinished)
		{
			return;
		}
		if (isUltimate && ultFinalShot)
		{
			if (ChaosStopwatch.Check(shotStopwatchID))
			{
				shotFinished = true;
				attackPosition = parent.attackOriginTrans.position;
				SoundManager.PlayWithDistAndSPR("StandardThrow", attackPosition);
				for (int i = 0; i < projectileCount; i++)
				{
					ThrowFrostFanProjectile(attackPosition + perpendOffset, targetVecList[i]);
					ThrowFrostFanProjectile(attackPosition - perpendOffset, targetVecList[projectileCount - 1 - i]);
				}
			}
		}
		else
		{
			switch (ChaosStopwatch.CheckInterval(shotStopwatchID))
			{
			case StopwatchState.Ready:
				ThrowFrostFanProjectile(parent.attackOriginTrans.position, targetVecList[shotCounter]);
				shotCounter++;
				break;
			case StopwatchState.Done:
				shotFinished = true;
				break;
			}
		}
	}

	private void ThrowFrostFanProjectile(Vector2 givenPosition, Vector2 givenVector)
	{
		currentFP = (FrostFanProjectile)CreateProjectile(FrostFanProjectile.Prefab, givenPosition + givenVector, Globals.GetRotationQuaternion(givenVector));
		if (IsEmpowered)
		{
			currentFP.disableOnHit = false;
			currentFP.flyTime *= 1.25f;
		}
		FireProjectile(currentFP, givenVector, setKnockbackVector: true, 0f, 0f, string.Empty);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(2, givenPosition + givenVector);
	}
}

