public class FrostBlock : MonoBehaviour
{
	private static GameObject prefab;

	public Animator anim;

	public ParticleSystem blastSys;

	private Transform followTrans;

	private float lifeTime;

	private int lifeStopwatchID;

	private bool destroyQueued;

	private string skillCat = string.Empty;

	private string skillID = string.Empty;

	private int skillLvl;

	private float burstRadius = 2f;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/FrostBlock.prefab"));

	public void Init(Transform givenTrans, float givenTime, string givenCat, string givenID, int givenLvl, float givenRadius)
	{
		followTrans = givenTrans;
		lifeTime = givenTime;
		skillCat = givenCat;
		skillID = givenID;
		skillLvl = givenLvl;
		burstRadius = givenRadius;
	}

	public void StopFollow()
	{
		if (!destroyQueued)
		{
			followTrans = null;
		}
	}

	private void Start()
	{
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime);
	}

	private void Update()
	{
		if (!destroyQueued && ChaosStopwatch.Check(lifeStopwatchID))
		{
			destroyQueued = true;
			followTrans = null;
			Vector2 vector = transform.position;
			IceBurst.CreateBurst(vector, skillCat, skillID, skillLvl, burstRadius);
			ParticleEffect poolItem = PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect");
			poolItem.Emit(20, vector, IceBoss.unfortifyEffectOverrides);
			poolItem.Emit(15, vector + Vector2.up, IceBoss.unfortifyEffectOverrides);
			poolItem.Emit(12, vector + Vector2.up * 2f, IceBoss.unfortifyEffectOverrides);
			if (anim != null)
			{
				anim.Play("Hide");
			}
			if (blastSys != null)
			{
				blastSys.Emit(100);
			}
			SoundManager.PlayWithDistAndSPR("Shatter", vector);
			SoundManager.PlayWithDistAndSPR("IceBlast", vector);
			SoundManager.PlayWithDistAndSPR("ImpactIce", vector);
			CameraController.ShakeCamera(0.5f);
			Object.Destroy(gameObject, 1f);
		}
	}

	private void LateUpdate()
	{
		if (followTrans != null)
		{
			transform.position = followTrans.position;
		}
	}
}
