	public void ArmTrap()
	{
		if (!armCompleted)
		{
			armCompleted = true;
			anim.speed = 1f;
			durationStopwatchID = ChaosStopwatch.Begin(duration);
		}
	}

	private void Explode()
	{
		if (!explodeCompleted)
		{
			explodeCompleted = true;
			anim.Play("Explode");
			blastEmitter.Emit(200);
			PoolManager.GetPoolItem<ParticleEffect>("IceFloorBurst").Emit(30, transform.position);
			SoundManager.PlayWithDistAndSPR("IceExplode", transform.position);
		}
