	public class SummonIceWaveState : SkillState
	{
		public new static string staticID = "SummonIceWave";

		private int waveCount = 5;

		private int ultCounter;

		private IceWaveBase currentIW;

		private Vector2 currentPosition;

		public override string OnEnterAnimStr => (!isUltimate) ? base.OnEnterAnimStr : parent.GSlamAnimStr;

		public SummonIceWaveState(FSM parentFSM, Player parentEntity)
			: base(staticID, parentFSM, parentEntity)
		{
			hasSignatureVariant = true;
			SetAnimTimes(0.2f);
			InitChargeSkillSettings(2, 0f, skillData, this);
		}

		public override void SetEmpowered(bool givenStatus, BoolVarStatMod givenMod)
		{
			base.SetEmpowered(givenStatus, givenMod);
			waveCount = ((!IsEmpowered) ? 5 : 7);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			if (isUltimate)
			{
				StartCooldownTimer(10f);
				SetSkillLevel(2);
			}
			else
			{
				SetSkillLevel(1);
			}
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			currentPosition = parent.transform.position;
			if (isUltimate)
			{
				ultCounter = 0;
				foreach (GameObject item in Entity.GetAllTargetsInRange(GameController.enemies, currentPosition, 12f, playerTagOnly: false, parent.playerSummonsList, parent.gameObject))
				{
					if (!(item == null))
					{
						CreateIceWave((ultCounter != 0) ? (currentPosition + UnityEngine.Random.insideUnitCircle.normalized) : currentPosition, inputVector);
						SetUltVars(item.transform);
						ultCounter++;
						if (ultCounter > 5)
						{
							break;
						}
					}
				}
				if (ultCounter == 0)
				{
					for (int i = 0; i < 3; i++)
					{
						CreateIceWave(currentPosition, Globals.GetRotatedCircleVector(3, i, inputVector));
						SetUltVars(parent.transform);
					}
				}
			}
			else
			{
				CreateIceWave(currentPosition, inputVector);
			}
			CameraController.ShakeCamera(0.2f);
		}

		private void CreateIceWave(Vector2 givenPos, Vector2 givenVec)
		{
			currentIW = ChaosInst<IceWaveBase>(IceWaveBase.Prefab, givenPos + givenVec);
			currentIW.moveVector = givenVec;
			currentIW.SetSkillData(parent.skillCategory, skillID, currentLevel, isUltimate);
			currentIW.spacing = 1.25f;
			currentIW.spawnRate = 0.05f;
			currentIW.maxWaveCount = waveCount;
			currentIW.spawnReturnWave = !isUltimate;
		}

		private void SetUltVars(Transform givenTrans)
		{
			currentIW.maxWaveCount = 40;
			currentIW.spawnWaveThroughStopLayermask = true;
			currentIW.homing = true;
			currentIW.homingBias = 8;
			currentIW.homingDelay = 0f;
			currentIW.parentObject = parent.gameObject;
			currentIW.targetTrans = givenTrans;
		}
	}

