using System.Collections;
using UnityEngine;

public class IceWaveBase : Wave
{
	public delegate void ActivateEventHandler();

	private new static GameObject prefab;

	private static string formAnimName = "Form";

	[HideInInspector]
	public bool playFormAnim;

	private string originalAnimName;

	[HideInInspector]
	public bool disableLights;

	protected Light[] wavePoolLights;

	public bool spawnReturnWave = true;

	private IceWaveBase returnWave;

	private Vector2 returnCheck;

	public ActivateEventHandler activateEventHandler;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/IceWaveBase.prefab"));

	public override void Start()
	{
		base.Start();
		wavePoolLights = new Light[wavePoolSize];
		for (int i = 0; i < wavePoolSize; i++)
		{
			wavePoolLights[i] = wavePoolTrans[i].Find("ProjectileLight").GetComponent<Light>();
			wavePoolLights[i].gameObject.SetActive(!disableLights);
		}
		stopLayerMask = ChaosCollisions.layerAllWall;
		originalAnimName = waveAnimName;
	}

	public override void Update()
	{
		if (playFormAnim)
		{
			playFormAnim = false;
			waveAnimName = formAnimName;
			ActivateWave();
			ChangeInterval(spawnRate, maxWaveCount, initSpawnRate);
			waveAnimName = originalAnimName;
			if (lerpSpacing)
			{
				lerpStopwatchID = ChaosStopwatch.Begin(lerpSpacingTime + initSpawnRate);
			}
		}
		base.Update();
	}

	public override void FixedUpdate()
	{
		if (!playFormAnim)
		{
			base.FixedUpdate();
		}
	}

	public override void ActivateWave()
	{
		base.ActivateWave();
		if (wavePoolAttacks[waveCount] != null && wavesElapsed == maxWaveCount)
		{
			wavePoolAttacks[waveCount].atkInfo.knockbackMultiplier = 1f;
		}
		if (waveCount % 2 == 0)
		{
			SoundManager.PlayWithDistAndSPR(waveSoundID, activationPosition);
		}
		if (!layerMaskHit)
		{
			PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter").Emit(3, wavePoolTrans[waveCount].position + Vector3.up, ParticleEffectOverrides.Radius1p5);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(8, wavePoolTrans[waveCount].position);
		}
		if (activateEventHandler != null)
		{
			activateEventHandler();
		}
	}

	public override Vector2 GetHomingVector(Vector2 wavePosition)
	{
		if (waveIsUltimate && targetTrans != null)
		{
			homingVector = (homingVector * (homingBias - 1) + ((Vector2)targetTrans.position - wavePosition).normalized) / homingBias;
		}
		else
		{
			base.GetHomingVector(wavePosition);
		}
		return homingVector;
	}

	public override void StopWave(bool stop = true)
	{
		base.StopWave(stop);
		if (stop && spawnReturnWave)
		{
			StartCoroutine(CreateReturnWave());
		}
	}

	public override void OnNegate()
	{
		spawnReturnWave = false;
		base.OnNegate();
	}

	private IEnumerator CreateReturnWave()
	{
		yield return new WaitForSeconds(spawnRate);
		returnCheck = Vector2.zero;
		if (hitStopLayerMask)
		{
			lastWavePosition += -moveVector * spacing;
		}
		else
		{
			returnCheck = lastWavePosition + moveVector * spacing;
			if (Globals.CheckCircle(returnCheck, 0.125f, stopLayerMask))
			{
				lastWavePosition = returnCheck;
			}
		}
		returnWave = Globals.ChaosInst<IceWaveBase>(Prefab, transform.parent, lastWavePosition);
		returnWave.moveVector = (origin - lastWavePosition).normalized;
		returnWave.maxWaveCount = wavesElapsed + (hitStopLayerMask ? (-1) : ((lastWavePosition == returnCheck) ? 1 : 0));
		returnWave.SetSkillData(waveSkillCategory, waveSkillID, waveSkillLevel, waveIsUltimate);
		returnWave.spawnAtOrigin = spawnAtOrigin;
		returnWave.spacing = spacing;
		returnWave.spawnRate = spawnRate;
		returnWave.spawnReturnWave = false;
	}
}
