using UnityEngine;

public class AquaBeam : Beam
{
	private static GameObject prefab;

	private float ogBeamThickness = 1f;

	private ParticleEffect pEffect;

	private ParticleSystem pSys;

	private ParticleSystem.ShapeModule pSysShapeMod;

	private ParticleSystem.EmissionModule pSysEmMod;

	private static AudioSource beamAudioSource;

	private WaterStreakEffect[] waterStreakEffects;

	private int waterStreakCount = 10;

	private int waterStreakIndex;

	private WaterDropEmitter waterDropEffect;

	private ParticleSystemOverride waterDropOverride = new ParticleSystemOverride
	{
		startSpeed = 18f,
		radius = 0.5f
	};

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AquaBeam.prefab"));

	public override void Awake()
	{
		base.Awake();
		Transform transform = base.transform.Find("WaterDropEmitter");
		pEffect = transform.GetComponent<ParticleEffect>();
		pSys = transform.GetComponent<ParticleSystem>();
		pSysShapeMod = pSys.shape;
		pSysEmMod = pSys.emission;
		waterStreakEffects = new WaterStreakEffect[waterStreakCount];
		for (int i = 0; i < waterStreakCount; i++)
		{
			waterStreakEffects[i] = Globals.ChaosInst<WaterStreakEffect>(WaterStreakEffect.Prefab, base.transform);
			waterStreakEffects[i].transform.localPosition = Vector3.zero;
			waterStreakEffects[i].transform.localEulerAngles = Vector3.zero;
			waterStreakEffects[i].moveSpeed = travelSpeed * 0.75f;
		}
	}

	public override void Start()
	{
		base.Start();
		anim.Play("Active", -1, 0f);
		string audioID = "AquaBeamStart";
		Transform originTrans = transform;
		SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		ogBeamThickness = beamThickness;
		pEffect.Play();
		for (int i = 0; i < waterStreakCount; i++)
		{
			waterStreakEffects[i].Initialize(beamTipTrans);
			waterStreakEffects[i].transform.localScale = widthScaleVec;
		}
		waterDropEffect = PoolManager.GetPoolItem<WaterDropEmitter>();
		waterDropEffect.Emit(14, transform.position, WaterDropEmitter.LargeWaterExplosionOverride);
		waterDropEffect.Play(40f, transform.position, waterDropOverride);
	}

	public override void Update()
	{
		if (beamAudioSource == null || !beamAudioSource.isPlaying)
		{
			string audioID = "AquaBeamLoop";
			Transform originTrans = transform;
			beamAudioSource = SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
	}

	public override void PlayOnReadyEffect()
	{
		waterStreakEffects[waterStreakIndex].Initialize(beamTipTrans);
		waterStreakIndex++;
		if (waterStreakIndex >= waterStreakCount)
		{
			waterStreakIndex = 0;
		}
		beamThickness = ogBeamThickness + Random.Range(0f, 0.125f) * ((!(Random.value > 0.5f)) ? 1f : (-1f));
	}

	private void LateUpdate()
	{
		pSysEmMod.rateOverTime = 12f * currentRange;
		pSysShapeMod.box = new Vector3(beamThickness, currentRange);
		pSys.transform.localPosition = new Vector2(0f, currentRange * 0.5f);
	}

	public override void StopBeam()
	{
		base.StopBeam();
		if (beamAudioSource != null && beamAudioSource.isPlaying)
		{
			beamAudioSource.Stop();
		}
		for (int i = 0; i < waterStreakCount; i++)
		{
			waterStreakEffects[i].Disable();
		}
		if (waterDropEffect != null)
		{
			waterDropEffect.Stop();
		}
		pSys.Stop();
		pSys.transform.SetParent(null);
		pSys.Emit((int)(5f * currentRange));
		Object.Destroy(pSys.gameObject, 1f);
	}

	private void OnDestroy()
	{
		if (waterDropEffect != null)
		{
			waterDropEffect.Stop();
		}
		if (pEffect != null)
		{
			pEffect.Stop();
		}
		if (pSys != null)
		{
			pSys.Stop();
		}
	}
}
