	[HideInInspector]
	public float duration = 2.5f;

	[HideInInspector]
	public int maxHitCount = 10;

	public bool ignoreDestroy;

	private bool queuedForDestroy;

	private int hitCDStopwatchID;

	private float hitDelay;

	[HideInInspector]
	public Attack attackBox;

	private CircleCollider2D attackCollider;

	[HideInInspector]
	public bool showCastCircle = true;

	[HideInInspector]
	public bool playSound = true;

	private ParticleSystem[] particleSystems;

	private Light blizLight;

	[HideInInspector]
	public CastingCircle castingCircle;

	[HideInInspector]
	public bool spinCastingCircle;

	[HideInInspector]
	public Color? castingCircleColor;

	[HideInInspector]
	public Movement movement;

	[HideInInspector]
	public bool useMovement;

	[HideInInspector]
	public bool useOrbit;

	private Vector2 orbitPosition = Vector2.zero;

	private ChaosQuickStopwatch orbitStopwatch;

	private float orbitLerpVal;

	private bool orbitLerpCompleted;

	[HideInInspector]
	public bool disableHitStun = true;

	private Vector2 animSpeedRange = new Vector2(2f, 5f);

	private int icicleSpawnCount = 1;

	private Vector3 icicleSpawnOffset;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/Blizzard.prefab"));

	private void Awake()
	{
		attackBox = transform.Find("BlizzardAttack").GetComponent<Attack>();
		attackCollider = attackBox.GetComponent<CircleCollider2D>();
		attackCollider.enabled = false;
		particleSystems = GetComponentsInChildren<ParticleSystem>();
		blizLight = GetComponentInChildren<Light>();
		movement = GetComponent<Movement>();
	}

	private void Start()
	{
		currentScale = transform.localScale.x;
		currentAtkRadius = attackCollider.radius;
		if (showCastCircle)
		{
			if (castingCircle == null)
			{
				string animName = ((!spinCastingCircle) ? "DrawInsideOut" : "Draw");
				Vector3 position = transform.position;
				float unitSizeX = transform.localScale.x * currentAtkRadius;
				Color? color = castingCircleColor;
				castingCircle = CastingCirclePool.Spawn(animName, position, disableWithParentVal: true, null, trackParentVal: true, useCastTimeVal: false, 0f, unitSizeX, 0f, color, 0.05f);
			}
			castingCircle.SetParent(gameObject);
			castingCircle.disableWithParent = true;
			castingCircle.trackParent = useMovement || useOrbit;
		}
		maxHitCount = Mathf.Max(0, maxHitCount);
		hitDelay = duration / (float)maxHitCount;
		hitCDStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, maxHitCount);
		if (playSound)
		{
			string animName = "Blizzard";
			Transform originTrans = transform;
			SoundManager.PlayAudioWithDistance(animName, null, originTrans);
		}
		icicleStopwatch = new ChaosQuickStopwatch(icicleSpawnInterval);
		icicleSpawnCount = Mathf.CeilToInt(currentScale);
		for (int num = particleSystems.Length - 1; num >= 0; num--)
		{
			particleSystems[num].transform.localScale *= currentScale;
		}
	}

	private void SpawnIcicle(bool flash = false)
	{
		icicleSpawnOffset = (Vector3)Random.insideUnitCircle * currentAtkRadius * currentScale;
		PoolManager.GetPoolItem<BlizzardIcicle>().Emit(transform.position + icicleSpawnOffset, 4f - icicleSpawnOffset.y, flash);
	}

	private void Update()
	{
		if (ignoreDestroy || queuedForDestroy || icicleStopwatch.IsRunning)
		{
			return;
		}
		icicleStopwatch.IsRunning = true;
		if (initialSpawnInterval)
		{
			initialSpawnInterval = false;
			for (int i = 0; i < 10; i++)
			{
				SpawnIcicle(flash: true);
			}
		}
		else
		{
			for (int j = 0; j < icicleSpawnCount; j++)
			{
				SpawnIcicle();
			}
		}
	}

	private void FixedUpdate()
	{
		if (ignoreDestroy || queuedForDestroy)
		{
			return;
		}
		if (useMovement)
		{
			movement.MoveToMoveVector();
