		{
			(durationStopwatch = new ChaosQuickStopwatch(duration)).IsRunning = true;
		}
	}

	public override void Update()
	{
		base.Update();
		if (iceDecoy != null && iceDecoy.currentStateName.Contains("Fall"))
		{
			Object.Destroy(gameObject);
			return;
		}
		if (useDuration)
		{
			if (durationStopwatch.IsRunning)
			{
				return;
			}
		}
		else if (!anim.AnimPlayed())
		{
			return;
		}
		if (!attackStarted)
		{
			attackStarted = true;
			anim.Play("Chomp", -1, 0f);
			CameraController.ShakeCamera();
			PoolManager.GetPoolItem<AnimEffect>("WaterBombExplosion").Play(transform.position + Vector3.up, string.Empty);
