	{
		attack.ChangeAttackInfoLevel(biteAtkLevel);
		SoundManager.PlayAudioWithDistance("SummonSharkExplosion", transform.position);
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(3, transform.position + Vector3.up);
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(3, transform.position + Vector3.up * 1.5f);
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(3, transform.position + Vector3.up * -1.5f);
		CameraController.ShakeCamera(1f, ignoreShakeCount: true);
		PoolManager.GetPoolItem<AnimEffect>("WaterBombExplosion").Play(transform.position + Vector3.up, string.Empty);
	}

	public void ChompEndEffect()
	{
	}
}

