using System;
using System.Collections.Generic;
using Chaos.AnimatorExtensions;
using Chaos.ListExtensions;
using UnityEngine;

public class Seeker : Entity
{
	public delegate void SeekerDeadEventHandler(Seeker givenSeeker);

	public class SeekerIdleState(string stName, FSM stFSM, Seeker stEnt) : State<Seeker>(stName, stFSM, stEnt)
	{
		private NumVarStatMod followMod = new NumVarStatMod("Follow", 10f, 10, VarStatModType.Override);

		private NumVarStatMod animSpeedMod = new NumVarStatMod("Follow", 3f, 10, VarStatModType.Multiplicative);

		private FacingDirection currentDirection;

		private List<GameObject> usedTargetsList;

		private TargetInfo targetInfo;

		public bool homing;

		public bool collidersEnabled;

		public override void OnEnter()
		{
			homing = false;
			parent.movement.moveSpeedStat.AddMod(followMod);
			if (!targetDict.ContainsKey(parent.ClusterID))
			{
				parent.ClusterID = "Empty";
			}
		}

		public override void Update()
		{
			if (!parent.thrownItem.throwComplete)
			{
				return;
			}
			if (!collidersEnabled)
			{
				collidersEnabled = true;
				SetColliderStatus(givenStatus: true);
			}
			if (parent.gameObject == null || !parent.durationStopwatch.IsRunning)
			{
				fsm.ChangeState("Dead");
				return;
			}
			if (!homing)
			{
				usedTargetsList = targetDict[parent.ClusterID];
				targetInfo = Entity.GetClosestTarget(parent.targetList, parent.transform.position, parent.homingRadius, playerTagOnly: false, usedTargetsList, parent.parentObject, requireLOS: true, parent.lineOfSightLayerMask);
				homing = targetInfo != null && targetInfo.transform != null;
				if (!homing)
				{
					if (Vector2.Distance(parent.transform.position, parent.FollowTransform.position) > parent.followDistance)
					{
						HandleMovement(parent.FollowTransform);
					}
					return;
				}
				parent.movement.moveSpeedStat.RemoveMod(followMod);
				parent.animSpeedHandler.Modify(animSpeedMod, givenStatus: true);
				parent.atkColActivated = true;
				if (parent.splitTargets && !usedTargetsList.Contains(targetInfo.gameObject))
				{
					usedTargetsList.Add(targetInfo.gameObject);
				}
			}
			if (targetInfo.transform == null)
			{
				fsm.ChangeState("Dead");
			}
			else
			{
				HandleMovement(targetInfo.transform);
			}
		}

		public override void OnExit()
		{
			if (targetInfo != null && targetInfo.gameObject != null)
			{
				usedTargetsList.Remove(targetInfo.gameObject);
			}
			usedTargetsList.RemoveNullValues();
		}

		public virtual void HandleMovement(Transform givenTrans)
		{
			if (!(givenTrans == null))
			{
				parent.movement.MoveToTarget(givenTrans);
				currentDirection = Globals.GetPrimaryDirection(parent.movement.moveVector);
				if (parent.facingDirection != currentDirection)
				{
					parent.anim.PlayDirectional("Roll" + currentDirection);
					parent.facingDirection = currentDirection;
				}
			}
		}

		public virtual void SetColliderStatus(bool givenStatus)
		{
			if (parent.hurtBoxCollider != null)
			{
				parent.hurtBoxCollider.enabled = givenStatus;
			}
			if (parent.floorCollider != null)
			{
				parent.floorCollider.enabled = givenStatus;
			}
		}
	}

