	protected static Dictionary<string, List<GameObject>> targetDict = new Dictionary<string, List<GameObject>>();

	private static Color outlineColor = new Color(0f, 1f, 1f, 0.6f);

	private string clusterID = string.Empty;

	public float followDistance = 3f;

	public float homingRadius = 10f;

	public bool splitTargets = true;

	public bool isEmpowered;

	public ThrownItem thrownItem;

	private ChaosQuickStopwatch durationStopwatch = new ChaosQuickStopwatch();

	private GameObject parentObject;

	private Transform parentTrans;

	private Transform followTrans;

	private HealthBar healthBar;

	private CastBar durationBar;

	public SeekerDeadEventHandler onDeadEventHandlers;

	private Collider2D atkCollider;

	private bool atkColEnabled;

	protected bool atkColActivated;

	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.25f);

	public bool isEnemy;

	protected List<GameObject> targetList;

	public int startingHealth = 5;

	public string ClusterID
	{
		get
		{
			return clusterID;
		}
		set
		{
			clusterID = value;
			if (!targetDict.ContainsKey(clusterID))
			{
				targetDict[clusterID] = new List<GameObject>();
			}
		}
	}

	protected Transform FollowTransform
	{
		get
		{
			Transform result;
			if (followTrans != null)
			{
				result = followTrans;
			}
			else
			{
				result = ((!(parentTrans != null)) ? transform : parentTrans);
			}
			return result;
		}
	}

	public void SetDuration(float givenTime)
	{
		durationStopwatch.SetDelay(givenTime, stopCurrent: false, autoStart: true);
	}

	public override void Awake()
	{
		disablePreventFallCollider = true;
		base.Awake();
		thrownItem = GetComponent<ThrownItem>();
		facingDirection = FacingDirection.Neutral;
		InitFSM();
	}

	public virtual void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new SeekerIdleState("Idle", fsm, this));
		fsm.AddState(new SeekerFallState("Fall", fsm, this));
		fsm.AddState(new SeekerDeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void Start()
	{
		base.Start();
		health.healthStat.SetInitialBaseValue(startingHealth);
		if (SummonedEntity.useHealthOverride)
		{
			health.healthStat.AddMod(SummonedEntity.healthOverrideMod);
		}
		Attack attack = base.attack;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(HandleCollision));
		Attack attack2 = base.attack;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(HandleCollision));
		atkCollider = base.attack.collider;
		atkCollider.enabled = false;
		atkColEnabled = false;
		atkColActivated = false;
		SetAffiliation();
		if (isEnemy)
		{
			splitTargets = false;
			homingRadius = 10f;
			followDistance = 5f;
			health.healthStat.AddMod(EnemyGlobalStatManager.healthMod);
			movement.moveSpeedStat.AddMod(new NumVarStatMod("EnemySeeker", -0.6f, 10, VarStatModType.Multiplicative));
			if (spriteRenderer != null)
			{
				spriteRenderer.material.SetColor("_OutlineColor", outlineColor);
			}
		}
		else
		{
			healthBar = Globals.ChaosInst<HealthBar>(HealthBar.Prefab);
			healthBar.parentTrans = transform;
			healthBar.parentHealth = health;
			healthBar.SetBarDimensions(0.46f, 0.54f, 0.45f, 0.46f);
			durationBar = Globals.ChaosInst<CastBar>(CastBar.Prefab);
			durationBar.parentTrans = transform;
			durationBar.SetBarDimensions(0.46f, 0.54f, 0.44f, 0.45f);
			durationBar.StartCast(durationStopwatch.ID, givenStatus: false);
		}
	}

	public void SetAffiliation()
	{
		if (isEnemy)
		{
			targetList = GameController.allies;
			hurtBoxCollider.gameObject.name = "EnemyHurtBox";
			hurtBoxCollider.gameObject.layer = LayerMask.NameToLayer("Enemy");
			floorContact.name = "EnemyFloorContact";
		}
		else
		{
			targetList = GameController.enemies;
			hurtBoxCollider.gameObject.name = "AllyHurtBox";
			hurtBoxCollider.gameObject.layer = LayerMask.NameToLayer("Player");
			floorContact.name = "AllyFloorContact";
		}
	}

	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (atkColActivated && !atkStopwatch.IsRunning)
		{
			if (!atkColEnabled)
			{
				atkColEnabled = true;
				atkCollider.enabled = true;
				atkStopwatch.IsRunning = true;
			}
			else
			{
				atkColEnabled = false;
				atkCollider.enabled = false;
			}
		}
	}

	public virtual void SetTransforms(Transform givenParent, Transform givenFollow, List<GameObject> excludeList = null)
	{
		followTrans = givenFollow;
		parentTrans = givenParent;
		if (parentTrans != null)
		{
			parentObject = parentTrans.gameObject;
		}
		if (excludeList != null)
		{
			targetDict[ClusterID].AddRange(excludeList);
			targetDict[ClusterID].RemoveNullValues();
		}
	}

	public virtual void SetThrowPosition(Vector2 givenPosition)
	{
		if (thrownItem != null)
		{
			thrownItem.targetPosition = givenPosition;
		}
	}

	public virtual void HandleCollision(Entity givenEnt)
	{
		fsm.ChangeState("Dead");
	}

	public virtual void Reset()
	{
		fsm.ChangeState(fsm.defaultStateName, allowSelfTransition: true);
		atkCollider.enabled = false;
		atkColEnabled = false;
		atkColActivated = false;
	}

	public virtual void OnDead()
	{
		if (base.attack != null)
		{
			Attack attack = base.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(HandleCollision));
		}
		if (onDeadEventHandlers != null)
		{
			onDeadEventHandlers(this);
		}
		if (gameObject != null)
		{
			UnityEngine.Object.Destroy(gameObject);
		}
	}

	public virtual void PlaySeekerAudio()
	{
	}
}

	public class UseBaseMinion : SkillState
	{
		public GameObject minionPrefab;

		public List<BasicMinion> minionList = new List<BasicMinion>();

		public BasicMinion currentMinion;

		public SyncedNumVarStat maxSummonStat = new SyncedNumVarStat(3f);

		public int summonCount = 1;

		public int currentCount;

		public Vector2 spawnLocation;

		public Vector2 spawnOffset;

		public float summonDuration;

		public int summonHealth;

		public override string OnEnterAnimStr => parent.PBAoEAnimStr;

		public UseBaseMinion(string newName, FSM newFSM, Player newPlayer)
			: base(newName, newFSM, newPlayer)
		{
			isSummonSkill = true;
			SetAnimTimes(0.1f, 0.2f, 0.3f, 0.8f, 0.9f);
		}

		public override void OnEnter()
		{
			base.OnEnter();
			parent.odPauseStopwatch.IsRunning = true;
		}

		public override void ExecuteSkill()
		{
			base.ExecuteSkill();
			summonCount = skillData.GetValue<int>(StatData.spawnStr);
			summonDuration = skillData.GetValue<float>(StatData.durStr);
			summonHealth = skillData.GetValue<int>(StatData.healthStr);
			spawnLocation = parent.transform.position;
			SummonAllMinions();
			CameraController.ShakeCamera(0.25f);
		}

		public virtual void LimitToMaxMinions()
		{
			if ((float)minionList.Count > maxSummonStat.CurrentValue && minionList[0] != null)
			{
				minionList[0].DestroyMinion();
				minionList.RemoveAt(0);
			}
		}

		public virtual void SummonAllMinions()
		{
			minionList.RemoveNullValues();
			parent.CleanUpPlayerSummonsList();
			for (currentCount = 0; currentCount < summonCount; currentCount++)
			{
				SummonMinion();
				LimitToMaxMinions();
			}
		}

		public virtual BasicMinion SummonMinion()
		{
			currentMinion = ChaosInst<BasicMinion>(minionPrefab, GetSpawnLocation());
			currentMinion.gameObject.name = minionPrefab.name + parent.skillCategory;
			currentMinion.parentTrans = parent.transform;
			currentMinion.parentSummonList = parent.playerSummonsList;
			currentMinion.SetSkillInfo(parent.skillCategory, skillID, currentLevel, isUltimate);
			currentMinion.summonDuration = summonDuration;
			currentMinion.startingHealth = summonHealth;
			currentMinion.isEmpowered = IsEmpowered;
			if (Inventory.EitherPlayerHasItem(FlatDamage.staticID) && FlatDamage.damageMod != null)
			{
				currentMinion.health.damageTakenStat.Modify(FlatDamage.damageMod, addMod: true);
			}
			minionList.Add(currentMinion);
			parent.playerSummonsList.Add(currentMinion.gameObject);
			return currentMinion;
		}

		public virtual Vector2 GetSpawnLocation()
		{
			spawnOffset = Entity.GetAvailableNearbyLocation(spawnLocation + Globals.GetRotatedCircleVector(summonCount, currentCount, inputVector), excludeOrigin: false, randomize: false);
			return (!(spawnOffset == Vector2.zero)) ? spawnOffset : spawnLocation;
		}
	}

