using UnityEngine;

public class WaterMinion : BasicMinion
{
	public class WaterMinionAttackState : State<WaterMinion>
	{
		private Vector2 atkPosition;

		private Vector2 targetPosition;

		private Vector2 targetVector;

		private int delayStopwatchID;

		private bool atkCompleted;

		private WaterMinionProjectile currentWP;

		public WaterMinionAttackState(string newName, FSM newFSM, WaterMinion newEnt)
			: base(newName, newFSM, newEnt)
		{
		}

		public override void OnEnter()
		{
			targetPosition = parent.closestTargetInfo.hurtBoxTransform.position;
			delayStopwatchID = ChaosStopwatch.Begin(parent.atkWindTime);
			atkCompleted = false;
		}

		public override void Update()
		{
			if (ChaosStopwatch.Check(delayStopwatchID))
			{
				if (!atkCompleted)
				{
					atkCompleted = true;
					atkPosition = parent.hurtBoxTransform.position;
					Vector2 normalized = (targetPosition - atkPosition).normalized;
					ShootProjectiles(atkPosition, normalized);
					delayStopwatchID = ChaosStopwatch.Begin(parent.atkExitTime);
					parent.anim.Play("Attack", -1, 0f);
					parent.movement.moveVector = -normalized;
					parent.movement.MoveToMoveVector(parent.movement.dashSpeedStat.CurrentValue);
					WaterDropEmitter.EmitCircle(parent.transform.position, 1, 8, 0.25f);
					WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
					int? particleCount = 1;
					Vector3? position = atkPosition + normalized * 0.15f;
					Vector3? localEulerAngles = Globals.GetRotationVector(normalized);
					poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
					PoolManager.GetPoolItem<WaterDropEmitter>().Emit(10, parent.transform.position, WaterDropEmitter.LargeWaterExplosionOverride);
					CameraController.ShakeCamera(0.3f);
					string audioID = "AquaBeamStart";
					Vector2? soundOrigin = parent.transform.position;
					float overridePitch = Random.Range(1.15f, 1.25f);
					SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
				}
				else
				{
					fsm.ChangeState(fsm.defaultStateName);
				}
			}
		}

		private void ShootProjectiles(Vector2 givenPosition, Vector2 givenVector)
		{
			int num = Mathf.FloorToInt((float)parent.atkCount * 0.5f);
			for (int i = -num; i <= num; i++)
			{
				targetVector = Globals.GetRotatedCircleVector(parent.atkSpread, i, givenVector);
				currentWP = Globals.ChaosInst<WaterMinionProjectile>(WaterMinionProjectile.Prefab, parent.transform.parent, givenPosition, Globals.GetRotationQuaternion(targetVector));
				currentWP.parentObject = parent.gameObject;
				currentWP.attackBox.SetAttackInfo(parent.skillCategory, parent.skillID);
				currentWP.attackBox.knockbackOverwriteVector = targetVector;
				currentWP.moveVector = targetVector;
				currentWP.Show();
			}
		}
	}

	private static GameObject prefab;

	private int atkCount = 5;

	private int atkSpread = 25;

	private float atkWindTime = 0.25f;

	private float atkExitTime = 1f;

	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Allies/WaterMinion.prefab"));

	public override void InitFSM()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new MinionIdleState("Idle", fsm, this)
		{
			animName = "Idle"
		});
		fsm.AddState(new FollowParentState("FollowParent", fsm, this)
		{
			animName = "Run"
		});
		fsm.AddState(new MoveToEnemyState("MoveToEnemy", fsm, this)
		{
			animName = "Run"
		});
		fsm.AddState(new WaterMinionAttackState("Attack", fsm, this));
		fsm.AddState(new MinionHurtState("Hurt", fsm, this));
		fsm.AddState(new MinionDeadState("Dead", fsm, this)
		{
			deadAudioID = "AquaPrisonLoop"
		});
		fsm.ChangeState(fsm.defaultStateName);
	}

	public override void Start()
	{
		base.Start();
		if (isEnemy)
		{
			atkCount = 3;
			atkWindTime = 0.35f;
			atkExitTime = 2f;
		}
		else if (isEmpowered)
		{
			atkCount = 7;
			atkSpread = 28;
		}
	}

	public override void PlaySpawnEffect(Vector2 givenPosition)
	{
		WaterDropEmitter.EmitCircle(givenPosition + Vector2.up, 2, 18, 1f);
		string audioID = "AquaVortex";
		Vector2? soundOrigin = givenPosition + Vector2.up;
		float overridePitch = Random.Range(1.15f, 1.25f);
		SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
	}

	public void PlayDeadEffects()
	{
		PoolManager.GetPoolItem<ParticleEffect>("WaterExplosion").Emit(1, spriteRenderer.transform.position);
		SoundManager.PlayAudioWithDistance("AquaPrisonImpact", spriteRenderer.transform.position);
	}
