public class AquaDragon : MonoBehaviour
{
	public class IdleState : State<AquaDragon>
	{
		private float sqStartRadius = 2f;
		private float sqExitRadius = 4f;
		private float sqDistToParent;
		private ChaosQuickStopwatch targetStopwatch = new ChaosQuickStopwatch(0.25f);
		private Vector2 followVector;
		private bool isOrbiting;
		private NumVarStatMod moveSpeedMod;
		public IdleState(string newName, FSM newFSM, AquaDragon newEnt)
			: base(newName, newFSM, newEnt)
		{
			sqStartRadius = parent.orbitRadius;
			sqExitRadius += sqStartRadius;
			sqStartRadius *= sqStartRadius;
			sqExitRadius *= sqExitRadius;
			moveSpeedMod = new NumVarStatMod("OrbitSpeedMod", 12f, 10, VarStatModType.Override);
		}
		public override void OnEnter()
		{
		}
		public override void FixedUpdate()
		{
			if (!targetStopwatch.IsRunning)
			{
				targetStopwatch.IsRunning = true;
				if (parent.UpdateTargetInfo() != null)
				{
					fsm.ChangeState("Attack");
					return;
				}
			}
			if (parent.followTrans == null)
			{
				return;
			}
			followVector = parent.followTrans.position - parent.transform.position;
			sqDistToParent = followVector.sqrMagnitude;
			if (isOrbiting)
			{
				if (sqDistToParent < sqExitRadius)
				{
					parent.MoveToVector(Globals.GetPerpendicular(followVector.normalized));
					return;
				}
				isOrbiting = false;
				parent.movement.moveSpeedStat.Modify(moveSpeedMod, addMod: false);
				parent.SetTargetVector(followVector.normalized);
			}
			else if (sqDistToParent < sqStartRadius)
			{
				isOrbiting = true;
				parent.movement.moveSpeedStat.Modify(moveSpeedMod, addMod: true);
				parent.SetTargetVector(Globals.GetPerpendicular(followVector.normalized));
			}
			else
			{
				parent.MoveToVector(followVector.normalized);
			}
		}
		public override void OnExit()
		{
			parent.movement.moveSpeedStat.Modify(moveSpeedMod, addMod: false);
		}
	}
	public class AttackState(string newName, FSM newFSM, AquaDragon newEnt) : State<AquaDragon>(newName, newFSM, newEnt)
	{
		private ChaosQuickStopwatch targetStopwatch = new ChaosQuickStopwatch(0.5f);
		private Vector2 attackVector;
		private NumVarStatMod moveSpeedMod = new NumVarStatMod("AtkSpeedMod", 12f, 10, VarStatModType.Override);
		private ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(3f);
		public override void OnEnter()
		{
			Attack attack = parent.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = parent.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			parent.movement.moveSpeedStat.Modify(moveSpeedMod, addMod: true);
		}
		public override void FixedUpdate()
		{
			if (targetStopwatch.IsRunning)
			{
				parent.MoveToVector();
			}
			else if (parent.closestTargetInfo == null || parent.closestTargetInfo.hurtBoxTransform == null)
			{
				if (parent.UpdateTargetInfo() == null)
				{
					fsm.ChangeState(fsm.defaultStateName);
					return;
				}
				parent.SetTargetVector(GetAttackVector());
				parent.MoveToVector();
			}
			else
			{
				parent.MoveToVector(GetAttackVector());
			}
		}
		public override void OnExit()
		{
			Attack attack = parent.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			parent.movement.moveSpeedStat.Modify(moveSpeedMod, addMod: false);
		}
		private void OnTargetHit(Entity givenEntity)
		{
			if (givenEntity != null && !(givenEntity is Destructible))
			{
				targetStopwatch.IsRunning = true;
			}
			parent.closestTargetInfo = null;
			if (!audioStopwatch.IsRunning)
			{
				audioStopwatch.IsRunning = true;
				SoundManager.PlayWithDistAndSPR("AquaWhoosh", parent.transform.position);
			}
		}
		private Vector2 GetAttackVector()
		{
			if (parent.closestTargetInfo == null || parent.closestTargetInfo.hurtBoxTransform == null)
			{
				return Vector2.zero;
			}
			attackVector = (parent.closestTargetInfo.hurtBoxTransform.position - parent.transform.position).normalized;
			return attackVector;
		}
	}
	public class DeadState : State<AquaDragon>
	{
		private NumVarStatMod moveSpeedMod;
