				parent.atkTransArr[i].Second.enabled = false;
				PoolManager.GetPoolItem<ParticleEffect>("WaterExplosion").Emit(1, parent.atkTransArr[i].First.transform.position, ParticleEffectOverrides.StartColorAlpha0p5);
			}
			PoolManager.GetPoolItem<ParticleEffect>("WaterExplosion").Emit(1, parent.transform.position, ParticleEffectOverrides.StartColorAlpha0p25);
			UnityEngine.Object.Destroy(parent.gameObject);
		}
		public override void Update()
		{
		}
	}
	private static GameObject prefab;
	private FSM fsm;
	public Animator anim;
	public Rigidbody2D rigidbody2D;
	public Movement movement;
	public Attack attack;
	public Transform spriteTrans;
	[HideInInspector]
	public Transform followTrans;
	[HideInInspector]
	public List<GameObject> targetGroup;
	private TargetInfo closestTargetInfo;
	private float targetRange = 12f;
	private float orbitRadius = 2f;
	private float targetSpeed = 3f;
	private Vector2 targetVector;
	private Vector2 currentVector;
	private Vector2 arcVector;
	private ChaosQuickStopwatch retargetStopwatch = new ChaosQuickStopwatch();
	private ChaosQuickStopwatch arcStopwatch = new ChaosQuickStopwatch(1.5f);
	private float arcLerpValue;
	private bool arcFlip;
	private int atkSegCount = 4;
	private Tuple<Transform, Attack>[] atkTransArr;
	private Tuple<Vector2, Vector2>[] atkPosAndDirArr;
	private int atkIndexStart;
	private int atkIndexPrev;
	private int atkIndexNext;
	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.0625f);
	private float atkLerpValue;
	public float lifeTime = 8f;
	private int lifeStopwatchID;
	private bool destroyQueued;
	private bool moveVecSet;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Areaeffects/AquaDragon.prefab"));
	private void Awake()
	{
		fsm = new FSM();
		fsm.defaultStateName = "Idle";
		fsm.AddState(new IdleState("Idle", fsm, this));
		fsm.AddState(new AttackState("Attack", fsm, this));
		fsm.AddState(new DeadState("Dead", fsm, this));
		fsm.ChangeState(fsm.defaultStateName);
		currentVector = Vector2.zero;
	}
	public void Initialize(Transform givenTransform, List<GameObject> givenGroup, Vector2 givenVector, bool givenFlip, bool givenEmpowered)
	{
		followTrans = givenTransform;
		targetGroup = givenGroup;
		arcFlip = givenFlip;
		if (givenEmpowered)
		{
			atkSegCount += 2;
		}
		currentVector = givenVector;
		SetTargetVector(currentVector);
		spriteTrans.localEulerAngles = Globals.GetRotationVector(currentVector);
	}
	private void Start()
	{
		atkTransArr = new Tuple<Transform, Attack>[atkSegCount];
		atkPosAndDirArr = new Tuple<Vector2, Vector2>[atkSegCount + 1];
		Vector2 vector = transform.position;
		for (int i = 0; i < atkSegCount + 1; i++)
		{
			atkPosAndDirArr[i] = new Tuple<Vector2, Vector2>(vector, currentVector);
			if (i != atkSegCount)
			{
				Attack attack = Globals.ChaosInst<Attack>(this.attack.gameObject, transform, vector);
				attack.ChangeAttackInfoLevel(2);
				attack.gameObject.AddComponent<Rigidbody2D>();
				attack.gameObject.SetActive(value: false);
				atkTransArr[i] = new Tuple<Transform, Attack>(attack.transform, attack);
			}
		}
		atkStopwatch.IsRunning = true;
		lifeStopwatchID = ChaosStopwatch.Begin(lifeTime + UnityEngine.Random.value);
		SoundManager.PlayWithDistAndSPR("AquaWhoosh", transform.position);
	}
	private TargetInfo UpdateTargetInfo()
	{
		if (followTrans == null)
		{
			return null;
		}
		closestTargetInfo = Entity.GetClosestTarget(targetGroup, followTrans.position, targetRange, playerTagOnly: false, null, gameObject, requireLOS: true, ChaosCollisions.layerUpperWall);
		return closestTargetInfo;
	}
	private void SetTargetVector(Vector2 givenVector)
	{
		targetVector = givenVector;
		retargetStopwatch.IsRunning = true;
	}
	private void MoveToVector(Vector2? givenVector = null)
	{
		if (retargetStopwatch.IsRunning)
		{
			currentVector = Vector2.Lerp(currentVector, targetVector, targetSpeed * Time.fixedDeltaTime).normalized;
			arcVector = Globals.GetPerpendicular(currentVector, arcFlip);
		}
		else if (givenVector.HasValue)
		{
			currentVector = Vector2.Lerp(currentVector, givenVector.Value, targetSpeed * Time.fixedDeltaTime).normalized;
			arcVector = Globals.GetPerpendicular(currentVector, arcFlip);
		}
		arcLerpValue = Mathf.PingPong(arcStopwatch.TimePercentage * 2f, 1f);
		arcVector = Vector2.Lerp(Vector2.zero, arcVector, arcLerpValue) * 0.707f;
		if (!arcStopwatch.IsRunning)
		{
			arcStopwatch.IsRunning = true;
			arcFlip = !arcFlip;
		}
		movement.moveVector = (currentVector + arcVector).normalized;
		movement.MoveToMoveVector();
		attack.knockbackOverwriteVector = movement.moveVector;
		if (!moveVecSet)
		{
			moveVecSet = true;
		}
	}
	private void Update()
	{
		if (fsm != null)
		{
			fsm.currentState.Update();
		}
	}
	private void FixedUpdate()
	{
		if (fsm != null)
		{
			fsm.currentState.FixedUpdate();
		}
	}
	private void LateUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		if (ChaosStopwatch.Check(lifeStopwatchID))
		{
			destroyQueued = true;
			fsm.ChangeState("Dead");
			return;
		}
		if (fsm != null)
		{
			fsm.currentState.LateUpdate();
		}
		if (moveVecSet && spriteTrans != null)
		{
			spriteTrans.localEulerAngles = Globals.GetRotationVector(movement.moveVector);
		}
		if (atkLerpValue >= 1f)
		{
			atkStopwatch.IsRunning = true;
			atkTransArr[atkIndexStart].First.gameObject.SetActive(value: true);
			atkIndexStart = (atkIndexStart + 1) % atkSegCount;
			for (int num = atkSegCount; num > 0; num--)
			{
				atkPosAndDirArr[num].First = atkPosAndDirArr[num - 1].First;
				atkPosAndDirArr[num].Second = atkPosAndDirArr[num - 1].Second;
			}
			atkPosAndDirArr[0].First = transform.position;
			atkPosAndDirArr[0].Second = movement.moveVector;
		}
		atkLerpValue = atkStopwatch.TimePercentage;
		for (int i = 0; i < atkSegCount; i++)
		{
			atkTransArr[i].First.position = Vector2.Lerp(atkPosAndDirArr[i + 1].First, atkPosAndDirArr[i].First, atkLerpValue);
			atkTransArr[i].Second.knockbackOverwriteVector = Vector2.Lerp(atkPosAndDirArr[i + 1].Second, atkPosAndDirArr[i].Second, atkLerpValue);
		}
	}
}

