using UnityEngine;
public class AquaBlitzBall : MonoBehaviour
{
	private static GameObject prefab;
	private Rigidbody2D rigidbody2D;
	public Animator anim;
	public Attack attack;
	public Vector2 idlePosition;
	public Vector2 idleVector;
	private ChaosQuickStopwatch idleStopwatch = new ChaosQuickStopwatch(1.25f);
	private ChaosQuickStopwatch resetStopwatch = new ChaosQuickStopwatch(2f);
	private ChaosQuickStopwatch moveStopwatch = new ChaosQuickStopwatch(0.1f);
	public bool activated;
	private Vector2 startPosition;
	private Vector2 atkPosition;
	private Vector2 atkVector;
	private float moveLerpValue;
	private bool moveCompleted;
	private bool destroyQueued;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/AquaBlitzBall.prefab"));
	private void Awake()
	{
		rigidbody2D = GetComponent<Rigidbody2D>();
	}
	private void Start()
	{
		startPosition = transform.position;
		idleStopwatch.IsRunning = true;
		resetStopwatch.IsRunning = true;
		PoolManager.GetPoolItem<WaterDropEmitter>().Emit(5, startPosition, WaterDropEmitter.MedWaterExplosionOverride);
		SoundManager.PlayWithDistAndSPR("AquaVortex", startPosition);
	}
	private void FixedUpdate()
	{
		if (activated)
		{
			if (!moveCompleted)
			{
				moveLerpValue = moveStopwatch.TimePercentage;
				rigidbody2D.MovePosition(Vector2.Lerp(startPosition, atkPosition, moveLerpValue));
				if (moveLerpValue >= 1f)
				{
					moveCompleted = true;
					anim.Play("Fire", -1, 0f);
					transform.rotation = Globals.GetRotationQuaternion(atkVector);
				}
			}
		}
		else if (!resetStopwatch.IsRunning)
		{
			Reset();
		}
		else
		{
			moveLerpValue = idleStopwatch.TimePercentage;
			rigidbody2D.MovePosition(Vector2.Lerp(transform.position, idlePosition, moveLerpValue));
		}
	}
	public void Activate(Vector2 givenPosition, Vector2 givenVector, Vector2 flyVector)
	{
		activated = true;
		moveStopwatch.IsRunning = true;
		startPosition = transform.position;
		atkPosition = givenPosition;
		atkVector = givenVector;
		transform.rotation = Globals.GetRotationQuaternion(flyVector);
		attack.knockbackOverwriteVector = atkVector;
		anim.Play("Attack", -1, 0f);
	}
	public void Reset()
	{
		if (destroyQueued)
		{
			return;
		}
		destroyQueued = true;
		if (activated)
		{
			SoundManager.PlayWithDistAndSPR("AquaSplash", atkPosition);
			WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
			int? particleCount = 1;
			Vector3? position = transform.position;
			Vector3? localEulerAngles = Globals.GetRotationVector(atkVector);
			poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
			if (gameObject != null)
			{
				Object.Destroy(gameObject, 1f);
			}
		}
		else
		{
			PoolManager.GetPoolItem<ParticleEffect>("WaterExplosion").Emit(1, transform.position);
			SoundManager.PlayWithDistAndSPR("WaterExplode", atkPosition);
			Object.Destroy(gameObject);
		}
	}
	public void RandomizeIdleAnim()
	{
		anim.Play("Idle", -1, Random.Range(0f, 1f));
	}
}
