	{
	}

	public override void SetBuffStatus(bool givenStatus)
	{
		base.SetBuffStatus(givenStatus);
		Player player = parent;
		player.skillExecEventHandlers = (SkillEventHandler)Delegate.Remove(player.skillExecEventHandlers, new SkillEventHandler(OnSkillUse));
		if (givenStatus)
		{
			Player player2 = parent;
