	{
		for (int num = parent.assignedSkills.Length - 1; num >= 0; num--)
		{
			LowerSkillCD(parent.assignedSkills[num]);
		}
		LowerSkillCD(parent.stockSkill);
		PlayVisual(parent.transform.position);
