using UnityEngine;
public class IceChakram : MonoBehaviour
{
	public Movement movement;
	[HideInInspector]
	public Transform parentTrans;
	public Attack attack;
	private Vector3 rotationVector;
	public float rotationsPerSecond;
	public float maxRadius;
	public float expandRate;
	[HideInInspector]
	public float orbitSpeed = 6f;
	public bool increaseMoveSpeed = true;
	public bool returnToCenter;
	public float minReturnRadius = 3f;
	private bool reverse;
	private ParticleEffect snowEmitter;
	private int spinDelayStopwatchID = -1;
	private float spinDelay = 0.2f;
	private bool spinLerpDone;
	public float resetDelay;
	private int resetStopwatchID;
	private bool resetQueued;
	private static GameObject _prefab;
	private static AudioSource spinAudio;
	public static GameObject Prefab
	{
		get
		{
			if (_prefab == null)
			{
				_prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/IceChakram.prefab");
			}
			return _prefab;
		}
	}
	private void Awake()
	{
		movement = GetComponent<Movement>();
		attack = GetComponentInChildren<Attack>();
	}
	private void Start()
	{
		spinDelayStopwatchID = ChaosStopwatch.Begin(spinDelay);
		rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 120f);
		movement.orbitSpeed = orbitSpeed;
		snowEmitter = PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter");
		snowEmitter.followTransform = transform;
		snowEmitter.Play();
		PlayAudio();
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(7, transform.position, ParticleEffectOverrides.Radius1p5);
	}
	private void FixedUpdate()
	{
		transform.Rotate(rotationVector * Time.fixedDeltaTime);
		if (!spinLerpDone && ChaosStopwatch.Check(spinDelayStopwatchID))
		{
			rotationVector = new Vector3(0f, 0f, rotationsPerSecond * 360f);
			spinLerpDone = true;
		}
		if (parentTrans == null)
		{
			return;
		}
		PlayAudio();
		if (!resetQueued)
		{
			movement.orbitRadius += expandRate * Time.fixedDeltaTime * (float)((!reverse) ? 1 : (-1));
		}
		if (reverse && movement.orbitRadius <= minReturnRadius)
		{
			if (!resetQueued)
			{
				resetQueued = true;
				resetStopwatchID = ChaosStopwatch.Begin(resetDelay);
				return;
			}
			if (ChaosStopwatch.Check(resetStopwatchID))
			{
				ResetChakram();
				return;
			}
		}
		if (movement.orbitRadius >= maxRadius)
		{
			if (returnToCenter)
			{
				reverse = true;
			}
			else
			{
				ResetChakram();
			}
			return;
		}
		if (increaseMoveSpeed)
		{
			movement.moveSpeedStat.SetInitialBaseValue(movement.orbitRadius * 1.6f);
		}
		movement.OrbitTarget(parentTrans.position);
	}
	private void ResetChakram()
	{
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(15, transform.position);
		snowEmitter.Stop();
		StopAudio();
		Object.Destroy(gameObject);
	}
	private void OnDestroy()
	{
		if (snowEmitter != null)
		{
			snowEmitter.Stop();
		}
	}
	private void PlayAudio()
	{
		if (spinAudio == null || !spinAudio.isPlaying)
		{
			string audioID = "BlizzardLoop";
			Transform originTrans = transform;
			spinAudio = SoundManager.PlayAudioWithDistance(audioID, null, originTrans);
		}
	}
	private void StopAudio()
	{
		if (spinAudio != null)
		{
			spinAudio.Stop();
			spinAudio = null;
		}
		SoundManager.PlayAudioWithDistance("IceExplode", transform.position, null, 24f, -1f, 1.25f);
	}
}

using System;
using UnityEngine;
public class IceBoomerang : Projectile
{
	private static GameObject prefab;
	private static ChaosQuickStopwatch audioStopwatch = new ChaosQuickStopwatch(0.125f);
	private Transform parentTrans;
	private bool isEmpowered;
	private bool isUltimate;
	private bool positiveArc;
	private float minSpeed;
	private float maxSpeed = 1f;
	private Vector3 minRoteVec;
	private Vector3 maxRoteVec;
	private float lerpValue;
	private bool targetHit;
	private ChaosQuickStopwatch retStopwatch = new ChaosQuickStopwatch(0.75f);
	private ChaosQuickStopwatch atkStopwatch = new ChaosQuickStopwatch(0.125f);
	private Collider2D atkCollider;
	private bool atkActive;
	private ChaosQuickStopwatch ultStopwatch = new ChaosQuickStopwatch(1.5f);
	private bool ultStarted;
	private bool ultCompleted;
	public SpriteRenderer spriteActual;
	public Sprite largeSprite;
	public Transform atkTrans;
	public Transform trailTrans;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/Projectiles/IceBoomerang.prefab"));
	public void Init(Transform givenTrans, bool isEmp, bool isUlt, bool givenArc)
	{
		parentTrans = givenTrans;
		isEmpowered = isEmp;
		isUltimate = isUlt;
		positiveArc = givenArc;
		if (isUltimate)
		{
			retStopwatch.SetDelay(2.5f);
		}
	}
	public override void Awake()
	{
		base.Awake();
		atkCollider = attackBox.GetComponent<Collider2D>();
	}
	public override void Start()
	{
		if (positiveArc)
		{
			projectileSpriteRenderer.transform.localScale = new Vector3(-1f, 1f, 1f);
			rotationsPerSecond = 0f - rotationsPerSecond;
		}
		base.Start();
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		Attack attack2 = attackBox;
		attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		maxSpeed = moveSpeed * 2f;
		minSpeed = 0f;
		maxRoteVec = rotationVector * 1.5f;
		minRoteVec = rotationVector * 0.5f;
		SoundManager.PlayWithDistAndSPR("IceSwordSwing", transform.position);
	}
	public override void Update()
	{
		if (CheckMaxLifeTime())
		{
			return;
		}
		if (ChaosStopwatch.Check(flyStopwatchID))
		{
			if (!boomerangReturning)
			{
				boomerangReturning = true;
				goThroughWalls = true;
				moveVector = -moveVector;
				moveSpeed = minSpeed;
				rotationVector = minRoteVec;
				attackBox.ChangeAttackInfoLevel((!isUltimate) ? 3 : 4);
				attackBox.damageOverride = -1;
				projectileStatData = null;
				atkStopwatch.IsRunning = true;
				retStopwatch.IsRunning = true;
				if (isEmpowered)
				{
					spriteActual.sprite = largeSprite;
					atkTrans.localScale = new Vector3(1.25f, 1.25f, 1f);
					trailTrans.localScale = new Vector3(1.5625f, 1.5625f, 1f);
				}
				SoundManager.PlayWithDistAndSPR("IceSolidify", transform.position);
				PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(8, transform.position);
			}
			if (!retStopwatch.IsRunning && (parentTrans == null || Vector2.Distance(transform.position, parentTrans.position) < returningSnapDistance))
			{
				ResetProjectile();
				return;
			}
		}
		if (attackBox != null)
		{
			attackBox.knockbackOverwriteVector = moveVector;
		}
		if (!audioStopwatch.IsRunning)
		{
			audioStopwatch.IsRunning = true;
			SoundManager.PlayWithDistAndSPR("StandardSpinSingle", transform.position);
		}
	}
	public override void FixedUpdate()
	{
		base.FixedUpdate();
		if (!boomerangReturning || !(parentTrans != null))
		{
			return;
		}
		lerpValue = Mathf.Pow(ChaosStopwatch.GetTimePercentage(lifeStopwatchID), 2f);
		moveSpeed = Mathf.Lerp(minSpeed, maxSpeed, lerpValue);
		rotationVector = Vector3.Lerp(minRoteVec, maxRoteVec, lerpValue);
		if (isUltimate && !ultCompleted)
		{
			if (!ultStarted)
			{
				ultStarted = true;
				ultStopwatch.IsRunning = true;
				moveVector = Vector2.zero;
			}
			if (!ultStopwatch.IsRunning)
			{
				ultCompleted = true;
				RefreshFlightTime();
			}
		}
		else
		{
			moveVector = (moveVector + (Vector2)(parentTrans.position - transform.position)).normalized;
		}
		if (atkActive)
		{
			atkActive = false;
			atkCollider.enabled = false;
		}
		if (!atkStopwatch.IsRunning)
		{
			atkStopwatch.IsRunning = true;
			atkCollider.enabled = false;
			atkCollider.enabled = true;
			atkActive = true;
		}
	}
	public override void ResetProjectile()
	{
		SoundManager.PlayAudioWithDistance("IceFormQuick", transform.position);
		SoundManager.PlayAudioWithDistance("Shatter", transform.position);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(15, transform.position);
		Attack attack = attackBox;
		attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
		base.ResetProjectile();
	}
	private void OnTargetHit(Entity givenEnt)
	{
		if (!targetHit && !boomerangReturning && !(givenEnt == null) && !(givenEnt is Destructible))
		{
			targetHit = true;
			ChaosStopwatch.Refresh(flyStopwatchID, 0.05f);
			ChaosStopwatch.Refresh(lifeStopwatchID, lifeTime);
		}
	}
}

public class UseIceChargeSwordBasic : NegMeleeState
{
	public new static string staticID = "UseIceChargeSwordBasic";

	private IceChargeSword firstSword;

	private IceChargeSword secondSword;

	private IceChargeSword currentIS;

	private bool prevFacingRight;

	public override string OnHoldAnimStr => parent.PBAoEAnimStr;

	public UseIceChargeSwordBasic(FSM parentFSM, Player parentEntity)
		: base(staticID, parentFSM, parentEntity)
	{
		isBasic = true;
		isMeleeSkill = true;
		skipAtkObjSpawn = true;
		attackPrefab = IceChargeSword.Prefab;
		setParent = false;
		destroyAttackObjectOnExit = false;
		maxComboCount = 3;
		animStartTime = 0.08f;
		animExecTime = 0.2f;
		baseCancelThreshold = 0.5f;
		finalCancelThreshold = 0.6f;
		baseRunThreshold = 0.7f;
		finalRunThreshold = 0.8f;
		baseExitThreshold = 1f;
		finalExitThreshold = 1f;
		sfxNames = new string[maxComboCount];
		for (int i = 0; i < maxComboCount; i++)
		{
			sfxNames[i] = "WindSlashBasic";
		}
		attackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 6f, 10, VarStatModType.OverrideWithMods);
		finalAttackMoveSpeedMod = new NumVarStatMod(atkMoveModStr, 12f, 10, VarStatModType.OverrideWithMods);
		chargeAtkMoveSpeed = 20f;
		autoHoldStat.BaseValue = true;
	}

	public override void OnEnter()
	{
		prevFacingRight = parent.isFacingRight;
		base.OnEnter();
		rotationVector = inputVector;
		if (prevFacingRight != parent.isFacingRight)
		{
			rotationVector.x *= -1f;
		}
		if (HitsRemaining > 0)
		{
			firstSword = CreateSword(comboCounter, isPrimary: true, isDouble: false, !parent.forehandAnimPlayed);
			secondSword = null;
		}
		else
		{
			firstSword = CreateSword(3, isPrimary: true, isDouble: true, isFlipped: true);
			secondSword = CreateSword(3, isPrimary: false, isDouble: true, isFlipped: false);
		}
		currentAttackObject = currentIS;
		parent.ToggleEnemyFloorCollisions(status: false);
	}

	public override void ExecuteAttack()
	{
		base.ExecuteAttack();
		if (firstSword != null)
		{
			firstSword.Swing(isCharged);
		}
		if (secondSword != null)
		{
			secondSword.Swing(isCharged);
		}
		if (isCharged)
		{
			CameraController.ShakeCamera(0.25f);
		}
		else if (firstSword != null && secondSword != null)
		{
			CameraController.ShakeCamera(0.18f);
		}
		else
		{
			CameraController.ShakeCamera(0.12f);
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		parent.ToggleEnemyFloorCollisions();
		if (firstSword != null)
		{
			firstSword.Reset(!attackExecuted);
		}
		if (secondSword != null)
		{
			secondSword.Reset(!attackExecuted);
		}
	}

	public override void OnCharged()
	{
		IceBurst.CreateBurst(parent.attackOriginTrans.position, string.Empty, string.Empty, 1, 1f);
		if (firstSword != null)
		{
			firstSword.OnCharged();
		}
		if (secondSword != null)
		{
			secondSword.OnCharged();
		}
	}

	private IceChargeSword CreateSword(int givenLevel, bool isPrimary, bool isDouble, bool isFlipped)
	{
		currentIS = ChaosInst<IceChargeSword>(attackPrefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(rotationVector), parent.attackOriginTrans);
		currentIS.Init(parent.skillCategory, skillID, givenLevel, inputVector, IsEmpowered, isPrimary, isDouble);
		if (isFlipped)
		{
			currentIS.transform.localScale = Globals.ScaleVecFlipX;
		}
		return currentIS;
	}
}

public class NegMeleeState(string newName, FSM newFSM, Player newPlayer) : MeleeAttackState(newName, newFSM, newPlayer)
{
	public delegate void ChargeEventHandler(Player player, NegMeleeState negMeleeState);

	public bool useCastBar = true;

	public SyncedNumVarStat chargeTimeStat = new SyncedNumVarStat(0.3f);

	public int chargeStopwatchID;

	public bool isCharged;

	public bool useBaseMAS;

	public bool allowCharge = true;

	public float chargeAtkMoveSpeed = 1f;

	public static ChargeEventHandler chargeEventHandlers;

	public float ChargePercentage => ChaosStopwatch.GetTimePercentage(chargeStopwatchID);

	public void NegPreCheck()
	{
		if (fsm.previousStateName != fsm.currentStateName)
		{
			comboCounter = 1;
		}
		useBaseMAS = !allowCharge || (autoHoldStat.CurrentValue && ((!repeatFinalHit && comboCounter < maxComboCount) || (repeatFinalHit && comboCounter < maxComboCount - 1)));
		holdReleased = false;
		attackExecuted = false;
		isCharged = false;
	}

	public override void OnEnter()
	{
		NegPreCheck();
		base.OnEnter();
		if (!useBaseMAS)
		{
			chargeStopwatchID = ChaosStopwatch.Begin(chargeTimeStat.CurrentValue);
			if (useCastBar)
			{
				parent.hud.castBar.StartCast(chargeStopwatchID, givenStatus: true);
			}
		}
	}

	public override bool MovementCheck()
	{
		if (useBaseMAS)
		{
			return base.MovementCheck();
		}
		movementVector = ((!base.MovementCheck()) ? Vector2.zero : inputVector);
		parent.movement.moveVector = movementVector;
		return false;
	}

