			attack.attackCollisionEventHandlers = (Attack.AttackCollisionEventHandler)Delegate.Remove(attack.attackCollisionEventHandlers, new Attack.AttackCollisionEventHandler(CheckCollision));
		}
		if (gameObject != null)
		{
			UnityEngine.Object.Destroy(gameObject);
		}
	}
	public virtual void CheckCollision(Collider2D col)
	{
		if (!collisionOccurred)
		{
			collisionOccurred = true;
		}
	}
	public void ChangeAttackLevel(int newLevel)
	{
		if (attack != null)
		{
			attack.ChangeAttackInfoLevel(newLevel);
		}
	}
	public void IncrementAttackLevel()
	{
		if (attack != null && attack.atkInfo != null)
		{
			ChangeAttackLevel(attack.atkInfo.skillLevel + 1);
		}
	}
}

	public class UseFrostSwing : SkillState
	{
		public new static string staticID = "UseFrostSwing";

		private int swingStopwatchID;

		private int swingCount;

		private float swingInterval = 0.25f;

		private ChaosQuickStopwatch moveStopwatch;

		private bool moveCompleted;

		private static int flipThreshold = 3;

		private int flipCounter;

		private bool flippedDirection;

		private Vector3 atkVector;

		private int atkCount;

		private bool atkStarted;

		private bool atkCompleted;

		private bool isFirst;

		private bool isFinal;

		private bool isVertAnim;

		private Vector3 camStartPos = Vector3.up;

		private bool useEmpowered;

		private float moveSpeed;

		private int AtkLevel => ((!useEmpowered) ? 1 : 3) + (isFinal ? 1 : 0);

		public override string OnEnterAnimStr => (!parent.isFacingRight) ? parent.BackhandAnimStr : parent.ForehandAnimStr;

		public UseFrostSwing(FSM parentFSM, Player parentEnt)
			: base(staticID, parentFSM, parentEnt)
		{
			hasSignatureVariant = true;
			isMovementSkill = true;
			isMeleeSkill = true;
			SetAnimTimes(0.15f, 0.2f, 0.25f, 0.55f, 0.75f);
			moveStopwatch = new ChaosQuickStopwatch(0.1f);
		}

		private void SetAtkVars()
		{
			if (isUltimate)
			{
				swingCount = 9;
				swingInterval = 0.12f;
			}
			else if (IsEmpowered)
			{
				swingCount = 3;
				swingInterval = 0.2f;
			}
			else
			{
				swingCount = 2;
				swingInterval = 0.25f;
			}
		}

		public override void OnEnter()
		{
			base.OnEnter();
			flippedDirection = false;
			flipCounter = 0;
			useEmpowered = IsEmpowered;
			if (useEmpowered)
			{
				SetCameraLock(givenStatus: true);
			}
			SetAtkVars();
			isVertAnim = parent.facingDirection == FacingDirection.Up || parent.facingDirection == FacingDirection.Down;
			parent.ToggleEnemyFloorCollisions(status: false);
			atkVector = inputVector;
			atkStarted = false;
			atkCompleted = false;
		}

		public override void ExecuteSkill()
		{
			if (!atkStarted)
			{
				atkStarted = true;
				swingStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, swingInterval, swingCount);
				atkCount = 0;
				flipCounter = 0;
				isFirst = true;
				moveCompleted = useEmpowered;
			}
			if (atkCompleted)
			{
				base.ExecuteSkill();
			}
		}

		public override void FixedUpdate()
		{
			if (atkCompleted || !atkStarted)
			{
				return;
			}
			switch (ChaosStopwatch.CheckInterval(swingStopwatchID))
			{
			case StopwatchState.Running:
				if (!moveCompleted && !moveStopwatch.IsRunning)
				{
					moveCompleted = true;
					parent.movement.EndMovement();
				}
				break;
			case StopwatchState.Ready:
				if (isFirst)
				{
					isFirst = false;
				}
				else
				{
					if (CancelToDash(enableButtonHeld: true))
					{
						break;
					}
					if (useEmpowered)
					{
						if (isUltimate)
						{
							if (flipCounter > flipThreshold)
							{
								atkVector = -atkVector;
								flipCounter = 0;
								flippedDirection = !flippedDirection;
							}
						}
						else
						{
							atkVector = -atkVector;
						}
						parent.FaceTarget(parent.transform.position + atkVector);
					}
					if (isUltimate)
					{
						parent.anim.PlayDirectional(parent.NextHandAnimStr, -1, animExecTime);
					}
					else
					{
						parent.anim.PlayDirectional((!useEmpowered || !isVertAnim) ? parent.NextHandAnimStr : parent.ForehandAnimStr, -1, animExecTime);
					}
				}
				isFinal = ++atkCount == swingCount;
				flipCounter++;
				parent.movement.moveVector = atkVector;
				if (isUltimate)
				{
					if (isFinal)
					{
						parent.movement.MoveToMoveVector(45f);
						SetCameraLock(givenStatus: false);
					}
					else
					{
						parent.movement.MoveToMoveVector(14f);
					}
				}
				else if (useEmpowered)
				{
					if (isFinal)
					{
						parent.movement.MoveToMoveVector(45f);
						SetCameraLock(givenStatus: false);
					}
					else
					{
						parent.movement.MoveToMoveVector(30f);
					}
				}
				else
				{
					parent.movement.MoveToMoveVector(30f);
					moveStopwatch.IsRunning = true;
					moveCompleted = false;
				}
				CreateFrostSwing();
				break;
			case StopwatchState.Done:
				atkCompleted = true;
				break;
			}
		}

		public override void OnExit()
		{
			base.OnExit();
			parent.ToggleEnemyFloorCollisions();
			if (useEmpowered)
			{
				SetCameraLock(givenStatus: false);
			}
		}

		private void SetCameraLock(bool givenStatus)
		{
			if (givenStatus)
			{
				camStartPos = parent.cameraLockTransform.localPosition;
				parent.cameraLockTransform.SetParent(null);
			}
			else
			{
				parent.cameraLockTransform.SetParent(parent.transform);
				parent.cameraLockTransform.localPosition = camStartPos;
			}
		}

		private void CreateFrostSwing()
		{
			FrostSwing frostSwing = ChaosInst<FrostSwing>(FrostSwing.Prefab, parent.attackOriginTrans.position, Globals.GetRotationQuaternion(atkVector));
			frostSwing.Init(parent.attackOriginTrans, parent.isFacingRight ^ parent.forehandAnimPlayed, isFinal);
			frostSwing.attack.SetAttackInfo(parent.skillCategory, skillID, AtkLevel, isUltimate);
			frostSwing.attack.knockbackOverwriteVector = atkVector;
			if (isUltimate && !isFinal)
			{
				frostSwing.attack.atkInfo.knockbackMultiplier = ((flipCounter <= flipThreshold) ? 10 : (-40));
			}
			if (isUltimate)
			{
				frostSwing.transform.localScale = (((atkCount % 2 != 0 || !flippedDirection) && (atkCount % 2 == 0 || flippedDirection)) ? Globals.ScaleVecFlipX : Vector3.one) * ((!isFinal) ? 1.25f : 1.65f);
				if (!isFinal)
				{
					frostSwing.transform.Rotate((atkCount % 2 != 0) ? Globals.Vector3Angle30CW : Globals.Vector3Angle30CCW);
				}
			}
			CameraController.ShakeCamera(0.25f);
		}
	}

