using UnityEngine;
public class FrostSwing : MonoBehaviour
{
	private static GameObject prefab;
	public Animator anim;
	public Attack attack;
	public Transform spriteTrans;
	private bool isFollowing;
	private Transform followTrans;
	private int followStopwatchID;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/FrostSwing.prefab"));
	public void Init(Transform givenTrans, bool givenFlip, bool givenFinal)
	{
		if (givenTrans != null)
		{
			isFollowing = true;
			followTrans = givenTrans;
			followStopwatchID = ChaosStopwatch.Begin(0.0625f);
		}
		if (givenFlip)
		{
			transform.localScale = Globals.Vector3NegativeX;
		}
		if (givenFinal)
		{
			anim.Play("SwingFinal", -1, 0f);
			SoundManager.PlayAudioWithDistance("StandardHeavySwing", transform.position);
		}
	}
	private void Start()
	{
		SoundManager.PlayWithDistAndSPR("FrostSwing", transform.position);
		SoundManager.PlayWithDistAndSPR("StandardHeavySwing", transform.position, 1.2f);
	}
	private void LateUpdate()
	{
		if (isFollowing)
		{
			if (followTrans == null || ChaosStopwatch.Check(followStopwatchID))
			{
				isFollowing = false;
			}
			else
			{
				transform.position = followTrans.position;
			}
		}
	}
	public void Reset()
	{
		isFollowing = false;
		followTrans = null;
		Object.Destroy(gameObject);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(5, spriteTrans.position, ParticleEffectOverrides.StartSpeed1);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(3, spriteTrans.TransformPoint(Vector3.up * 1.5f), ParticleEffectOverrides.StartSpeed1);
		PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(3, spriteTrans.TransformPoint(Vector3.up * 3f), ParticleEffectOverrides.StartSpeed1);
		PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter").Emit(2, spriteTrans.TransformPoint(Vector3.up * 1.5f));
		PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter").Emit(1, spriteTrans.TransformPoint(Vector3.up * 3f));
	}
}

