public class BaseJumpState : SkillState
{
	protected ThrownItem parentThrow;

	protected Vector2 startPosition;

	protected bool useCalcValues;

	protected float jumpRange = 5.5f;

	protected float jumpSpeed = 32f;

	protected float jumpTime = 0.5f;

	protected float jumpHeight = 1f;

	protected float jumpBalance = 0.5f;

	protected bool hasLanded;

	protected bool collidersEnabled;

	protected float landingDelay;

	protected ChaosQuickStopwatch landingStopwatch = new ChaosQuickStopwatch();

	public bool setInputVectorOnEnter = true;

	protected BoolVarStatMod airborneStatMod;

	public BaseJumpState(string skillID, FSM fsm, Player player)
		: base(skillID, fsm, player)
	{
		isMovementSkill = true;
		isJumpSkill = true;
		parentThrow = parent.throwScript;
		airborneStatMod = new BoolVarStatMod(skillID, newModValue: true, 3);
	}

	public override void OnEnter()
	{
		BaseOnEnter();
		base.ExecuteSkill();
		if (setInputVectorOnEnter)
		{
			inputVector = GetInputVector();
		}
		startPosition = parent.transform.position;
		parent.spriteRenderer.sortingLayerName = "UI";
		SetThrowValues();
		parentThrow.ThrowToTargetVector(Globals.GetSafeLinecastVector(startPosition, inputVector, jumpRange, ChaosCollisions.layerAllWallAndObst));
		landingStopwatch.SetDelay(landingDelay);
		SoundManager.PlayAudioWithDistance("StandardJump", startPosition);
		DustEmitter poolItem = PoolManager.GetPoolItem<DustEmitter>();
		int particleCount = 50;
		float scale = 0.25f;
		Vector3? emitPosition = startPosition;
		poolItem.EmitCircle(particleCount, scale, -1f, -1f, emitPosition);
		hasLanded = false;
		collidersEnabled = false;
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ThrownItem thrownItem2 = parentThrow;
		thrownItem2.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Combine(thrownItem2.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
		ToggleObjects(status: false);
	}

	public override void Update()
	{
		if (hasLanded)
		{
			if (!collidersEnabled)
			{
				collidersEnabled = true;
				ToggleObjects(status: true);
			}
			if (!landingStopwatch.IsRunning)
			{
				ExitToSkillOrRunOrIdle();
			}
		}
	}

	public override void OnExit()
	{
		if (!hasLanded)
		{
			OnLanding();
		}
		base.OnExit();
		ToggleObjects(status: true);
		ThrownItem thrownItem = parentThrow;
		thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
	}

	public virtual void OnLanding()
	{
		hasLanded = true;
		landingStopwatch.IsRunning = true;
		parent.spriteRenderer.sortingLayerName = "Actor";
	}

	public virtual void ToggleObjects(bool status)
	{
		parent.airborneStat.Modify(airborneStatMod, !status);
		if (parent.hurtBoxObj != null && parent.hurtBoxObj.activeSelf != status)
		{
			parent.hurtBoxObj.SetActive(status);
		}
		if (parent.floorContact != null && parent.floorContact.activeSelf != status)
		{
			parent.floorContact.SetActive(status);
		}
		parent.TogglePreventFallCollider(status);
	}

	public virtual void SetThrowValues()
	{
		parentThrow.useCalculatedValues = useCalcValues;
		parentThrow.moveSpeed = jumpSpeed;
		parentThrow.baseFlightTime = jumpTime;
		parentThrow.throwHeight = jumpHeight;
		parentThrow.isFallingThreshold = jumpBalance;
	}
}

public class BaseWardState : SkillState

public class UseWhirlpool : BaseJumpState
{
	public new static string staticID = "UseWhirlpool";

	private static float atkStartThreshold = 0.6f;

	private static float atkInterval = 0.08f;

	private WaterBallProjectile currentWB;

	private ParticleEffect waterFormEffect;

	private ParticleSystemOverride waterFormEffectOverride;

	private ParticleSystemOverride waterRingEffectOverride;

	private int atkLevel = 2;

	private int atkStopwatchID = -1;

	private int atkCount;

	private bool atkStarted;

	private bool atkDone;

	private float atkRadius;

	private float initialAtkRadius;

	private bool slamQueued;

	private bool slamFirstFrame;

	private bool skipAnimRefresh;

	private bool throwPaused;

	private Vector2 curPos;

	private Vector3 spriteScale = Vector3.one;

	private Vector3 holdOffset = Vector3.up;

	private AudioSource spinAudio;

	private GameObject tempFloorContact;

	private NumVarStatMod moveSpeedMod;

	public override string OnEnterAnimStr => (!isUltimate) ? parent.JumpAnimStr : "JumpSpin";

	public UseWhirlpool(FSM fsm, Player parentPlayer)
		: base(staticID, fsm, parentPlayer)
	{
		hasSignatureVariant = true;
		isMeleeSkill = true;
		applyStopElementStatus = true;
		SetAnimTimes();
		jumpRange = 0f;
		landingDelay = 0.15f;
		waterFormEffectOverride = new ParticleSystemOverride
		{
			startSpeed = -40f,
			startLifetime = 0.15f
		};
		moveSpeedMod = new NumVarStatMod(skillID, 6f, 10, VarStatModType.Override);
		waterRingEffectOverride = new ParticleSystemOverride();
	}

	public override void SetThrowValues()
	{
		if (isUltimate)
		{
			parent.movement.moveSpeedStat.AddMod(moveSpeedMod);
			jumpHeight = 4.75f;
			jumpTime = 0.5f;
			atkLevel = 4;
			atkCount = 20;
			atkRadius = 4f;
			spriteScale = Vector3.one;
			holdOffset = Vector3.up * 1.25f;
		}
		else if (IsEmpowered)
		{
			jumpHeight = 3.625f;
			jumpTime = 0.45f;
			atkLevel = 2;
			atkCount = 12;
			atkRadius = 3f;
			spriteScale = Globals.ScaleVec0p75;
			holdOffset = Vector3.up * 0.75f;
		}
		else
		{
			jumpHeight = 3f;
			jumpTime = 0.35f;
			atkLevel = 2;
			atkCount = 10;
			atkRadius = 2.5f;
			spriteScale = Globals.ScaleVec0p75;
			holdOffset = Vector3.up * 0.5f;
		}
		base.SetThrowValues();
		initialAtkRadius = atkRadius * 1.325f;
		waterFormEffectOverride.radius = initialAtkRadius;
		waterRingEffectOverride.radius = initialAtkRadius * 0.9f;
	}

	public override void ToggleObjects(bool status)
	{
		base.ToggleObjects(status);
		if (isUltimate && !(parent.floorContact == null))
		{
			if (!status)
			{
				tempFloorContact = UnityEngine.Object.Instantiate(parent.floorContact.gameObject, parent.floorContact.transform.position, Quaternion.identity, parent.floorContact.transform.parent);
				tempFloorContact.name = "TempFloorContact";
				tempFloorContact.SetActive(value: true);
				tempFloorContact.layer = LayerMask.NameToLayer("IgnoreEnemyAllyFloorContact");
				parentThrow.ignoreLineLerpPosition = true;
				parentThrow.updateFloorContact = false;
			}
			else if (tempFloorContact != null)
			{
				UnityEngine.Object.Destroy(tempFloorContact);
				parentThrow.ignoreLineLerpPosition = false;
				parentThrow.updateFloorContact = true;
			}
		}
	}

	public override void OnEnter()
	{
		base.OnEnter();
		curPos = parent.transform.position;
		parent.ToggleEnemyFloorCollisions(status: false);
		PoolManager.GetPoolItem<AttackGeneric>().CircleAttack(curPos, parent.skillCategory, skillID, 1, isUltimate, initialAtkRadius);
		atkStarted = false;
		atkDone = false;
		throwPaused = false;
		skipAnimRefresh = false;
		slamQueued = false;
		slamFirstFrame = false;
		parent.anim.PlayDirectional(OnEnterAnimStr, -1, animStartTime);
		SoundManager.PlayWithDistAndSPR("StandardJump", startPosition);
		SoundManager.PlayWithDistAndSPR("AquaBeamStart", startPosition, 0.9f);
		waterFormEffect = PoolManager.GetPoolItem<ParticleEffect>("WaterFormEffect");
		waterFormEffect.Emit((!isUltimate) ? 40 : 80, curPos, waterFormEffectOverride);
		waterFormEffect.Play(80f, curPos, playTime: atkStartThreshold * jumpTime, overrides: waterFormEffectOverride);
		PoolManager.GetPoolItem<ParticleEffect>("WaterRingEffect").Emit(100, curPos, waterRingEffectOverride);
		PoolManager.GetPoolItem<ParticleEffect>("WaterTwirlFormEffect").Emit(1, curPos);
	}

	public override void LateUpdate()
	{
		if (!(currentWB == null))
		{
			currentWB.transform.position = parent.attackOriginTrans.position + holdOffset;
			parentThrow.targetPosition = parent.transform.position;
		}
	}

	public override void FixedUpdate()
	{
		if (!parentThrow.isFalling || currentWB == null || atkDone)
		{
			return;
		}
		if (isUltimate && currentWB.movement != null)
		{
			parent.movement.moveVector = inputVector;
			parent.movement.MoveToMoveVector();
		}
		switch (ChaosStopwatch.CheckInterval(atkStopwatchID))
		{
		case StopwatchState.Ready:
			skipAnimRefresh = !skipAnimRefresh;
			if (skipAnimRefresh)
			{
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, 0.35f);
			}
			PoolManager.GetPoolItem<AttackGeneric>().CircleAttack(parent.transform.position, parent.skillCategory, skillID, atkLevel, isUltimate, atkRadius);
			break;
		case StopwatchState.Done:
			if (isUltimate)
			{
				GetInputVector(faceInputVector: true, useAimVector: false);
			}
			parentThrow.ResumeThrow();
			throwPaused = false;
			parent.anim.PlayDirectional(parent.FallAnimStr, -1, animStartTime);
			atkDone = true;
			PoolManager.GetPoolItem<ParticleEffect>("WaterExplosion").Emit(1, currentWB.transform.position);
			if (currentWB != null)
			{
				UnityEngine.Object.Destroy(currentWB.gameObject);
			}
			if (spinAudio != null)
			{
				spinAudio.Stop();
			}
			break;
		}
	}

	public override void Update()
	{
		curPos = parent.transform.position;
		if (!hasLanded)
		{
			if (isUltimate && atkStarted)
			{
				inputVector = GetInputVector(faceInputVector: false, useAimVector: false, ignoreZero: false);
			}
			if (!atkStarted && parentThrow.isFalling && parentThrow.PercentComplete >= atkStartThreshold)
			{
				atkStarted = true;
				atkStopwatchID = ChaosStopwatch.Begin(0f, useInterval: true, atkInterval, atkCount);
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animExecTime);
				parentThrow.PauseThrow();
				throwPaused = true;
				currentWB = ChaosInst<WaterBallProjectile>(WaterBallProjectile.Prefab, parent.attackOriginTrans.position + holdOffset);
				currentWB.EnableColliders(status: false);
				currentWB.enabled = false;
				currentWB.projectileSprite.transform.localScale = spriteScale;
				currentWB.projectileSpriteRenderer.enabled = true;
				currentWB.InitParticleSystem();
				currentWB.partSysShapeMod.radius = atkRadius;
				currentWB.anim.Play("IdleLarge", -1, 0f);
				if (parent.isFacingRight && parent.facingDirection != FacingDirection.Up)
				{
					currentWB.transform.localScale = Globals.Vector3NegativeX;
				}
				waterFormEffect.ClearAll();
				waterFormEffect.Stop();
				WaterHitEffect poolItem = PoolManager.GetPoolItem<WaterHitEffect>();
				int? particleCount = 1;
				Vector3? position = curPos + Vector2.up * jumpHeight * 0.725f;
				Vector3? localEulerAngles = Globals.GetRotationVector(Vector3.up);
				poolItem.EmitSingle(particleCount, position, null, localEulerAngles);
				PoolManager.GetPoolItem<WaterDropEmitter>().Emit(30, curPos + Vector2.up * jumpHeight * 0.8f, WaterDropEmitter.LargeWaterExplosionOverride);
				SoundManager.PlayAudioWithDistance("AquaVortex", startPosition);
				string audioID = "WaterLoop";
				Vector2? soundOrigin = curPos;
				float overridePitch = UnityEngine.Random.Range(0.85f, 0.95f);
				spinAudio = SoundManager.PlayAudioWithDistance(audioID, soundOrigin, null, 24f, -1f, overridePitch);
				CameraController.ShakeCamera(0.3f);
			}
		}
		else if (slamQueued)
		{
			if (slamFirstFrame)
			{
				slamFirstFrame = false;
				parent.anim.PlayDirectional(parent.GSlamAnimStr, -1, animExecTime);
				return;
			}
			slamQueued = false;
			PoolManager.GetPoolItem<AttackGeneric>().CircleAttack(curPos, parent.skillCategory, skillID, 3, isUltimate, atkRadius);
			CameraController.ShakeCamera(0.4f);
			PoolManager.GetPoolItem<AnimEffect>("WaterBombExplosion").Play(parent.attackOriginTrans.position, givenScale: atkRadius * 0.25f, localEulerAngles: Vector3.up, animName: string.Empty);
			SoundManager.PlayWithDistAndSPR("DelugeBomb", curPos);
		}
		else
		{
			base.Update();
		}
	}

	public override void OnExit()
	{
		base.OnExit();
		if (currentWB != null)
		{
			UnityEngine.Object.Destroy(currentWB.gameObject);
		}
		if (throwPaused)
		{
			parentThrow.ResumeThrow();
		}
		if (waterFormEffect != null)
		{
			waterFormEffect.Stop();
		}
		if (spinAudio != null)
		{
			spinAudio.Stop();
		}
		if (isUltimate)
		{
			parent.movement.moveSpeedStat.RemoveMod(moveSpeedMod);
		}
		parent.ToggleEnemyFloorCollisions();
	}

	public override void OnLanding()
	{
		base.OnLanding();
		slamQueued = true;
		slamFirstFrame = true;
		parent.airborneStat.RemoveMod(airborneStatMod);
	}
}

	public class UseFrostSurf : BaseJumpState
	{
		public new static string staticID = "UseFrostSurf";

		private static float dashCancelThreshold = 0.25f;

		private float duration;

		private int maxHitCount;

		private float hitDelay;

		private NumVarStatMod moveSpeedMod;

		private Vector2 lastInputVec;

		private Surfboard curSurfboard;

		private IcicleFormEffect icicleFormEffect;

		private AudioSource iceSFX;

		private ChaosQuickStopwatch dashTimer = new ChaosQuickStopwatch(0f);

		private ParticleEffect snowEmitter;

		public UseFrostSurf(FSM parentFSM, Player parentEnt)
			: base(staticID, parentFSM, parentEnt)
		{
			isMovementSkill = true;
			isMeleeSkill = true;
			isJumpSkill = false;
			SetAnimTimes(0.15f, 0.2f, 0.3f, 0.5f);
			moveSpeedMod = new NumVarStatMod(skillID, 16f, 10, VarStatModType.Override);
			jumpRange = 4f;
			jumpTime = 0.3f;
			jumpHeight = 1f;
			jumpBalance = 0.6f;
		}

		public override void OnEnter()
		{
			parent.movement.moveSpeedStat.AddMod(moveSpeedMod);
			InitSkillSettings();
			base.OnEnter();
			lastInputVec = inputVector;
			hasLanded = false;
			curSurfboard = Surfboard.Create(startPosition, parent.skillCategory, skillID, 1, 0.1f, jumpTime, 2, maxHitCount, inputVector, parent.transform);
			curSurfboard.attack.knockbackOverwriteVector = inputVector;
			parent.anim.PlayDirectional("SpinReverse");
			SoundManager.PlayAudioWithDistance("IceForm2", startPosition);
			CameraController.ShakeCamera(0.3f);
		}

		public override void Update()
		{
			if (!hasLanded)
			{
				base.Update();
				return;
			}
			inputVector = GetInputVector(faceInputVector: false, useAimVector: false);
			parent.FaceTarget(parent.transform.position + (Vector3)parent.movement.moveVector);
			parent.anim.PlayDirectional("Slide" + parent.facingDirection);
			if (!dashTimer.IsRunning)
			{
				parent.movement.dashVector = parent.movement.moveVector;
				fsm.ChangeState(SlideState.staticID);
			}
		}

		public override void FixedUpdate()
		{
			if (hasLanded && dashTimer.IsRunning)
			{
				inputVector = (Mathf.Lerp(0.1f, 0.2f, dashTimer.TimePercentage) * inputVector + lastInputVec).normalized;
				parent.movement.moveVector = inputVector;
				parent.movement.MoveToMoveVector();
				curSurfboard.atkVec = inputVector;
				lastInputVec = inputVector;
			}
		}

		public override void OnExit()
		{
			if (parent.skillExitEventHandlers != null)
			{
				parent.skillExitEventHandlers(this);
			}
			hasLanded = true;
			landingStopwatch.IsRunning = true;
			parent.spriteRenderer.sortingLayerName = "Actor";
			ToggleObjects(status: true);
			ThrownItem thrownItem = parentThrow;
			thrownItem.onLandingEventHandlers = (ThrownItem.OnLandingEventHandler)Delegate.Remove(thrownItem.onLandingEventHandlers, new ThrownItem.OnLandingEventHandler(OnLanding));
			parent.movement.EndMovement();
			parent.ToggleEnemyFloorCollisions();
			CleanUpObjects();
			parent.hud.castBar.EndCast();
		}

		private void StartDash()
		{
			Attack attack = curSurfboard.attack;
			attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			Attack attack2 = curSurfboard.attack;
			attack2.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Combine(attack2.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
			curSurfboard.attack.ChangeAttackInfoLevel(2);
			curSurfboard.anim.Play("Idle", -1, 0f);
			dashTimer.SetDelay(duration, stopCurrent: false, autoStart: true);
			parent.hud.castBar.StartCast(dashTimer.ID, givenStatus: false);
			ToggleObjects(status: false);
			parent.hurtBoxObj.SetActive(value: true);
			parent.floorContact.SetActive(value: true);
			parent.ToggleEnemyFloorCollisions(status: false);
			parent.movement.dashVector = inputVector;
			parent.movement.moveVector = inputVector;
			parent.movement.moveSpeedStat.AddMod(moveSpeedMod);
			snowEmitter = PoolManager.GetPoolItem<ParticleEffect>("SnowEmitter");
			snowEmitter.followTransform = parent.hurtBoxTransform;
			snowEmitter.reqFollowTrans = true;
			snowEmitter.Play(20f, parent.hurtBoxTransform.position);
			SoundManager.PlayAudioWithDistance("IceDash", startPosition);
		}

		private void BurstAttack(Vector2 givenPos)
		{
			IceBurst.CreateBurst(givenPos, parent.skillCategory, skillID, 3, 3f);
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(100, givenPos, ParticleEffectOverrides.RadiusTwo);
			SoundManager.PlayWithDistAndSPR("IceBlast", givenPos);
		}

		public override void OnLanding()
		{
			base.OnLanding();
			iceSFX = SoundManager.PlayAudio("IceField");
			if (icicleFormEffect != null)
			{
				icicleFormEffect.Stop();
			}
			ToggleObjects(status: true);
			StartDash();
		}

		private void InitSkillSettings()
		{
			hitDelay = 0.01f;
			if (IsEmpowered)
			{
				duration = 1.5f;
				maxHitCount = 15;
			}
			else
			{
				duration = 1.25f;
				maxHitCount = 12;
			}
		}

		private void CleanUpObjects()
		{
			parent.movement.moveSpeedStat.RemoveMod(skillID);
			if (icicleFormEffect != null)
			{
				icicleFormEffect.Stop();
			}
			if (snowEmitter != null)
			{
				snowEmitter.Stop();
			}
			if (curSurfboard != null)
			{
				Attack attack = curSurfboard.attack;
				attack.entityCollisionEventHandlers = (Attack.EntityCollisionEventHandler)Delegate.Remove(attack.entityCollisionEventHandlers, new Attack.EntityCollisionEventHandler(OnTargetHit));
				curSurfboard.DestroySurfboard();
			}
			if (iceSFX != null && iceSFX.isPlaying)
			{
				iceSFX.Stop();
			}
		}

		private void OnTargetHit(Entity givenEntity)
		{
			if (!(givenEntity == null) && !(givenEntity is Destructible) && !(givenEntity.health == null) && givenEntity.health.ignoreGrab)
			{
				BurstAttack(parent.transform.position);
				curSurfboard.DestroySurfboard();
				dashTimer.IsRunning = false;
			}
		}
	}

