using UnityEngine;
public class Surfboard : MonoBehaviour
{
	private static GameObject prefab;
	private static ParticleSystemOverride _iceEffectOverride;
	public Attack attack;
	public SpriteRenderer spriteRenderer;
	public SpriteRenderer shadowRenderer;
	public ParticleSystem frostEmitter0;
	public ParticleSystem frostEmitter1;
	public FollowTransform followScript;
	public Animator anim;
	public Vector2 atkVec;
	private float hitDelay = 1f;
	private int hitStopwatchID = -1;
	private int maxHitCount = 1;
	private int spawnMaxHitCount = 1;
	private float spawnDelay;
	private ChaosQuickStopwatch spawnTimer = new ChaosQuickStopwatch(0f);
	private bool surfStarted;
	private bool destroyQueued;
	public static GameObject Prefab => prefab ?? (prefab = ChaosBundle.Get("Assets/Prefabs/AreaEffects/Surfboard.prefab"));
	public static ParticleSystemOverride IceEffectOverride
	{
		get
		{
			if (_iceEffectOverride == null)
			{
				ParticleSystemOverride particleSystemOverride = new ParticleSystemOverride();
				particleSystemOverride.startLifetime = 0.66f;
				particleSystemOverride.sortingLayer = "Shadow";
				_iceEffectOverride = particleSystemOverride;
			}
			return _iceEffectOverride;
		}
	}
	private void Start()
	{
		if (spawnDelay > 0f)
		{
			spawnTimer.SetDelay(spawnDelay);
			spawnTimer.IsRunning = true;
			hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, spawnMaxHitCount);
		}
		else
		{
			Surf();
		}
	}
	private void Update()
	{
		if (!spawnTimer.IsRunning && !destroyQueued)
		{
			transform.localEulerAngles = Globals.GetRotationVector(atkVec);
		}
	}
	private void FixedUpdate()
	{
		if (destroyQueued)
		{
			return;
		}
		switch (ChaosStopwatch.CheckInterval(hitStopwatchID))
		{
		case StopwatchState.Running:
			attack.collider.enabled = true;
			attack.knockbackOverwriteVector = atkVec;
			break;
		case StopwatchState.Ready:
			attack.collider.enabled = false;
			PoolManager.GetPoolItem<ParticleEffect>("IcicleFloorBreakEffect").Emit(12, transform.position, IceEffectOverride);
			break;
		case StopwatchState.Done:
			if (!surfStarted)
			{
				Surf();
			}
			else
			{
				DestroySurfboard();
			}
			break;
		}
	}
	private void Surf()
	{
		surfStarted = true;
		hitStopwatchID = ChaosStopwatch.Begin(hitDelay, useInterval: true, hitDelay, maxHitCount);
		anim.Play("Idle", -1, 0f);
	}
	public static Surfboard Create(Vector3 spawnPos, string skillCategory, string skillID, int skillLevel = 1, float hitDelay = 1f, float spawnDelay = 0f, int spawnMaxHitCount = 1, int maxHitCount = 1, Vector2 atkVec = default(Vector2), Transform followTrans = null)
	{
		Surfboard surfboard = Globals.ChaosInst<Surfboard>(Prefab, null, spawnPos, Globals.GetRotationQuaternion(atkVec));
		surfboard.attack.SetAttackInfo(skillCategory, skillID, skillLevel);
		surfboard.spawnMaxHitCount = spawnMaxHitCount;
		surfboard.maxHitCount = maxHitCount;
		surfboard.hitDelay = hitDelay;
		surfboard.spawnDelay = spawnDelay;
		surfboard.atkVec = atkVec;
		surfboard.followScript.followTransform = followTrans;
		return surfboard;
	}
	public void DestroySurfboard()
	{
		if (!destroyQueued)
		{
			destroyQueued = true;
			attack.enabled = false;
			spriteRenderer.enabled = false;
			shadowRenderer.enabled = false;
			frostEmitter0.Stop();
			frostEmitter1.Stop();
			PoolManager.GetPoolItem<ParticleEffect>("IcicleBreakEffect").Emit(50, transform.position);
			SoundManager.PlayAudioWithDistance("IceExplode", transform.position);
			Object.Destroy(gameObject, 1f);
		}
	}
}
